-- ===== 20261014000001_core_schema.sql =====
-- Eliphas Indicus Publications: core schema
-- Tables: profiles, role_invites, settings, printers, books, orders, order_items, payouts
-- Every table has Row Level Security (RLS) on. The rules are at the bottom of this file.

-- ---------------------------------------------------------------------------
-- Types
-- ---------------------------------------------------------------------------
create type public.app_role as enum ('reader', 'author', 'printer', 'admin');

create type public.book_status as enum (
  'draft',             -- author is still editing
  'in_review',         -- submitted, waiting for admin
  'changes_requested', -- admin sent it back with a note
  'published',         -- live in the bookstore
  'unpublished'        -- taken down by author or admin
);

create type public.order_status as enum (
  'pending_payment', -- order created, Razorpay payment not finished
  'paid',            -- payment verified, waiting for printer
  'printing',        -- printer accepted the job
  'printed',         -- printed, waiting for courier
  'shipped',         -- handed to courier
  'delivered',
  'cancelled'
);

create type public.payout_status as enum ('pending', 'paid', 'cancelled');

-- ---------------------------------------------------------------------------
-- Helper: keep updated_at fresh
-- ---------------------------------------------------------------------------
create function public.touch_updated_at()
returns trigger language plpgsql as $$
begin
  new.updated_at = now();
  return new;
end $$;

-- ---------------------------------------------------------------------------
-- Profiles: one row per logged-in person (created automatically on first login)
-- ---------------------------------------------------------------------------
create table public.profiles (
  id          uuid primary key references auth.users (id) on delete cascade,
  phone       text unique,
  full_name   text,
  role        public.app_role not null default 'reader',
  city        text,
  state       text,
  pincode     text,
  -- Author payout details (filled later by the author)
  payout_upi  text,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);
create trigger profiles_touch before update on public.profiles
  for each row execute function public.touch_updated_at();

-- Phone numbers that should get a role other than "reader" on first login.
-- Admin adds a printer's phone here; when the printer logs in they become a printer.
create table public.role_invites (
  phone      text primary key,            -- E.164 without '+', e.g. 919876543210
  role       public.app_role not null,
  note       text,
  created_at timestamptz not null default now()
);

-- ---------------------------------------------------------------------------
-- Role helpers (security definer so RLS rules can call them without recursion)
-- ---------------------------------------------------------------------------
create function public.my_role()
returns public.app_role
language sql stable security definer set search_path = public as $$
  select role from public.profiles where id = auth.uid()
$$;

create function public.is_admin()
returns boolean
language sql stable security definer set search_path = public as $$
  select coalesce((select role = 'admin' from public.profiles where id = auth.uid()), false)
$$;

-- Create profile when a new auth user appears
create function public.handle_new_user()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  invited public.app_role;
begin
  select role into invited from public.role_invites where phone = new.phone;
  insert into public.profiles (id, phone, role)
  values (new.id, new.phone, coalesce(invited, 'reader'));
  return new;
end $$;

create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function public.handle_new_user();

-- People may edit their own profile, but only an admin may change a role,
-- except one self-service step: reader -> author ("I want to publish").
create function public.guard_profile_role()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if new.role is distinct from old.role
     and auth.uid() is not null           -- auth.uid() is null for SQL editor / service role
     and not public.is_admin()
     and not (old.role = 'reader' and new.role = 'author' and new.id = auth.uid()) then
    raise exception 'Only an admin can change this role';
  end if;
  if new.phone is distinct from old.phone and auth.uid() is not null and not public.is_admin() then
    raise exception 'Phone number cannot be changed here';
  end if;
  return new;
end $$;

create trigger profiles_guard_role before update on public.profiles
  for each row execute function public.guard_profile_role();

-- ---------------------------------------------------------------------------
-- Settings: editable values (print rates, fees) so prices change without code
-- ---------------------------------------------------------------------------
create table public.settings (
  key         text primary key,
  value       jsonb not null,
  description text,
  updated_at  timestamptz not null default now(),
  updated_by  uuid references public.profiles (id)
);
create trigger settings_touch before update on public.settings
  for each row execute function public.touch_updated_at();

-- ---------------------------------------------------------------------------
-- Printers: print partners. user_id links to the printer's login.
-- ---------------------------------------------------------------------------
create table public.printers (
  id            uuid primary key default gen_random_uuid(),
  name          text not null,
  contact_name  text,
  phone         text not null unique,     -- E.164 without '+'
  user_id       uuid unique references public.profiles (id) on delete set null,
  city          text not null,
  state         text not null,
  pincode       text,
  address       text,
  -- Optional per-printer rate overrides; same shape as settings.print_rates
  rate_overrides jsonb,
  active        boolean not null default true,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now()
);
create trigger printers_touch before update on public.printers
  for each row execute function public.touch_updated_at();

-- When someone logs in whose phone matches a printer, link the login to it.
create function public.link_printer_login()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if new.role = 'printer' then
    update public.printers set user_id = new.id
    where phone = new.phone and user_id is null;
  end if;
  return new;
end $$;

create trigger profiles_link_printer after insert or update of role on public.profiles
  for each row execute function public.link_printer_login();

-- ---------------------------------------------------------------------------
-- Books
-- ---------------------------------------------------------------------------
create table public.books (
  id              uuid primary key default gen_random_uuid(),
  author_id       uuid not null references public.profiles (id) on delete restrict,
  slug            text not null unique,
  title           text not null,
  subtitle        text,
  author_name     text not null,              -- name printed on the cover
  description     text,
  language        text not null default 'en' check (language in ('en', 'hi')),
  genre           text,
  isbn            text,
  -- Print options (keys must exist in settings.print_rates)
  page_count      integer check (page_count between 24 and 1000),
  trim_size       text not null default '5x8',
  binding         text not null default 'paperback',
  interior        text not null default 'bw',
  paper           text not null default 'cream',
  cover_finish    text not null default 'matte',
  -- Money, in rupees
  mrp             numeric(10, 2) check (mrp >= 0),
  print_cost      numeric(10, 2),             -- snapshot when submitted
  -- Files in Supabase Storage
  manuscript_path text,                       -- bucket: manuscripts (private)
  cover_path      text,                       -- bucket: covers (public)
  -- Review workflow
  status          public.book_status not null default 'draft',
  review_note     text,
  reviewed_by     uuid references public.profiles (id),
  reviewed_at     timestamptz,
  submitted_at    timestamptz,
  published_at    timestamptz,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now()
);
create index books_author_idx on public.books (author_id);
create index books_status_idx on public.books (status);
create trigger books_touch before update on public.books
  for each row execute function public.touch_updated_at();

-- Authors can only move a book between draft, in_review and unpublished.
-- Publishing and sending back is an admin action.
create function public.guard_book_status()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if auth.uid() is null or public.is_admin() then
    return new;
  end if;
  if tg_op = 'INSERT' then
    if new.status <> 'draft' then
      raise exception 'New books must start as draft';
    end if;
    return new;
  end if;
  if new.status is distinct from old.status then
    if not (
      (old.status in ('draft', 'changes_requested') and new.status = 'in_review') or
      (old.status = 'in_review' and new.status = 'draft') or
      (old.status = 'published' and new.status = 'unpublished') or
      (old.status = 'unpublished' and new.status = 'in_review')
    ) then
      raise exception 'Authors cannot move a book from % to %', old.status, new.status;
    end if;
  end if;
  -- A live book's content cannot be edited without going back through review
  if old.status in ('published', 'in_review') and new.status = old.status then
    raise exception 'This book is % and cannot be edited now', old.status;
  end if;
  new.reviewed_by := old.reviewed_by;
  new.reviewed_at := old.reviewed_at;
  new.published_at := old.published_at;
  new.author_id := old.author_id;
  return new;
end $$;

create trigger books_guard_status before insert or update on public.books
  for each row execute function public.guard_book_status();

-- ---------------------------------------------------------------------------
-- Orders (created by the server during checkout, never directly by the browser)
-- ---------------------------------------------------------------------------
create table public.orders (
  id                  uuid primary key default gen_random_uuid(),
  order_number        text not null unique
                        default ('EIP-' || to_char(now(), 'YYMMDD') || '-' ||
                                 upper(substr(md5(gen_random_uuid()::text), 1, 6))),
  buyer_id            uuid not null references public.profiles (id),
  status              public.order_status not null default 'pending_payment',
  -- Money, in rupees
  subtotal            numeric(10, 2) not null,
  shipping            numeric(10, 2) not null default 0,
  total               numeric(10, 2) not null,
  -- Razorpay
  razorpay_order_id   text unique,
  razorpay_payment_id text unique,
  -- Delivery address
  ship_name           text not null,
  ship_phone          text not null,
  ship_line1          text not null,
  ship_line2          text,
  ship_city           text not null,
  ship_state          text not null,
  ship_pincode        text not null,
  -- Fulfilment
  printer_id          uuid references public.printers (id),
  courier             text,
  tracking_number     text,
  paid_at             timestamptz,
  printed_at          timestamptz,
  shipped_at          timestamptz,
  delivered_at        timestamptz,
  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now()
);
create index orders_buyer_idx on public.orders (buyer_id);
create index orders_printer_idx on public.orders (printer_id);
create index orders_status_idx on public.orders (status);
create trigger orders_touch before update on public.orders
  for each row execute function public.touch_updated_at();

-- One line per book in an order. Money split is frozen at purchase time.
create table public.order_items (
  id             uuid primary key default gen_random_uuid(),
  order_id       uuid not null references public.orders (id) on delete cascade,
  book_id        uuid not null references public.books (id),
  author_id      uuid not null references public.profiles (id),
  quantity       integer not null check (quantity > 0),
  unit_price     numeric(10, 2) not null,  -- MRP
  print_cost     numeric(10, 2) not null,  -- per copy
  platform_fee   numeric(10, 2) not null,  -- per copy (Rs 15 by default)
  payment_fee    numeric(10, 2) not null,  -- per copy (gateway charges)
  author_earning numeric(10, 2) not null,  -- per copy
  created_at     timestamptz not null default now()
);
create index order_items_order_idx on public.order_items (order_id);
create index order_items_author_idx on public.order_items (author_id);
create index order_items_book_idx on public.order_items (book_id);

-- ---------------------------------------------------------------------------
-- Payouts to authors
-- ---------------------------------------------------------------------------
create table public.payouts (
  id           uuid primary key default gen_random_uuid(),
  author_id    uuid not null references public.profiles (id),
  amount       numeric(10, 2) not null check (amount > 0),
  status       public.payout_status not null default 'pending',
  reference    text,                -- UPI / bank UTR number
  note         text,
  period_start date,
  period_end   date,
  paid_at      timestamptz,
  created_by   uuid references public.profiles (id),
  created_at   timestamptz not null default now()
);
create index payouts_author_idx on public.payouts (author_id);

-- ---------------------------------------------------------------------------
-- Row Level Security
-- ---------------------------------------------------------------------------
alter table public.profiles     enable row level security;
alter table public.role_invites enable row level security;
alter table public.settings     enable row level security;
alter table public.printers     enable row level security;
alter table public.books        enable row level security;
alter table public.orders       enable row level security;
alter table public.order_items  enable row level security;
alter table public.payouts      enable row level security;

-- profiles
create policy "profiles: read own" on public.profiles
  for select using (id = auth.uid() or public.is_admin());
create policy "profiles: update own" on public.profiles
  for update using (id = auth.uid() or public.is_admin());

-- role_invites: admin only
create policy "role_invites: admin" on public.role_invites
  for all using (public.is_admin()) with check (public.is_admin());

-- settings: anyone can read (pricing page needs rates), admin edits
create policy "settings: public read" on public.settings
  for select using (true);
create policy "settings: admin write" on public.settings
  for all using (public.is_admin()) with check (public.is_admin());

-- printers
create policy "printers: admin" on public.printers
  for all using (public.is_admin()) with check (public.is_admin());
create policy "printers: read own" on public.printers
  for select using (user_id = auth.uid());

-- books
create policy "books: public reads published" on public.books
  for select using (status = 'published');
create policy "books: author reads own" on public.books
  for select using (author_id = auth.uid() or public.is_admin());
create policy "books: author creates" on public.books
  for insert with check (
    author_id = auth.uid() and public.my_role() in ('author', 'admin')
  );
create policy "books: author edits own" on public.books
  for update using (author_id = auth.uid() or public.is_admin())
  with check (author_id = auth.uid() or public.is_admin());
create policy "books: author deletes own draft" on public.books
  for delete using (
    (author_id = auth.uid() and status = 'draft') or public.is_admin()
  );

-- orders: buyers read their own; printers read/update assigned; admin all.
-- Inserts happen on the server with the service key, so no insert policy.
create policy "orders: buyer reads own" on public.orders
  for select using (buyer_id = auth.uid());
create policy "orders: printer reads assigned" on public.orders
  for select using (
    printer_id in (select id from public.printers where user_id = auth.uid())
  );
create policy "orders: admin" on public.orders
  for all using (public.is_admin()) with check (public.is_admin());

-- order_items
create policy "order_items: visible with order" on public.order_items
  for select using (
    exists (select 1 from public.orders o where o.id = order_id)  -- inherits orders RLS
  );
create policy "order_items: author reads own sales" on public.order_items
  for select using (author_id = auth.uid());
create policy "order_items: admin" on public.order_items
  for all using (public.is_admin()) with check (public.is_admin());

-- payouts
create policy "payouts: author reads own" on public.payouts
  for select using (author_id = auth.uid());
create policy "payouts: admin" on public.payouts
  for all using (public.is_admin()) with check (public.is_admin());

-- ---------------------------------------------------------------------------
-- Storage buckets
--   manuscripts: private PDFs. Path: <author_id>/<book_id>/manuscript.pdf
--   covers:      public images. Path: <author_id>/<book_id>/cover.jpg
-- ---------------------------------------------------------------------------
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values
  ('manuscripts', 'manuscripts', false, 52428800, array['application/pdf']),
  ('covers', 'covers', true, 10485760, array['image/jpeg', 'image/png', 'image/webp', 'application/pdf'])
on conflict (id) do nothing;

create policy "manuscripts: author uploads own folder" on storage.objects
  for insert to authenticated with check (
    bucket_id = 'manuscripts' and (storage.foldername(name))[1] = auth.uid()::text
  );
create policy "manuscripts: author updates own folder" on storage.objects
  for update to authenticated using (
    bucket_id = 'manuscripts' and (storage.foldername(name))[1] = auth.uid()::text
  );
create policy "manuscripts: author or admin reads" on storage.objects
  for select to authenticated using (
    bucket_id = 'manuscripts' and
    ((storage.foldername(name))[1] = auth.uid()::text or public.is_admin())
  );
create policy "manuscripts: author deletes own" on storage.objects
  for delete to authenticated using (
    bucket_id = 'manuscripts' and (storage.foldername(name))[1] = auth.uid()::text
  );

create policy "covers: author uploads own folder" on storage.objects
  for insert to authenticated with check (
    bucket_id = 'covers' and (storage.foldername(name))[1] = auth.uid()::text
  );
create policy "covers: author updates own folder" on storage.objects
  for update to authenticated using (
    bucket_id = 'covers' and (storage.foldername(name))[1] = auth.uid()::text
  );
create policy "covers: author deletes own" on storage.objects
  for delete to authenticated using (
    bucket_id = 'covers' and (storage.foldername(name))[1] = auth.uid()::text
  );
-- covers bucket is public, so reading needs no policy.

-- ===== 20261014000002_settings_defaults.sql =====
-- Default settings. These are SAMPLE print rates until real printer rates arrive.
-- Change them any time in Supabase: Table Editor -> settings -> edit the "value" JSON
-- (or from the admin screens in Milestone 4). No code change or redeploy needed.
--
-- Print cost per copy =
--     binding.base + cover_finish.extra
--   + page_count * (interior.per_page + paper.per_page_extra) * trim_size.page_multiplier
--   rounded up to the next rupee.
--
-- Author earning per copy =
--     MRP - print cost - fees.platform_fee_per_copy
--   - payment charges (MRP * gateway_percent% plus gateway_gst_percent% GST on that charge)

insert into public.settings (key, value, description) values
(
  'print_rates',
  '{
    "is_sample": true,
    "min_pages": 24,
    "max_pages": 800,
    "trim_sizes": {
      "5x8":     { "label": "5 × 8 in (novel)",           "page_multiplier": 1.00 },
      "5.5x8.5": { "label": "5.5 × 8.5 in (digest)",      "page_multiplier": 1.05 },
      "a5":      { "label": "A5 (148 × 210 mm)",           "page_multiplier": 1.05 },
      "6x9":     { "label": "6 × 9 in (non-fiction)",      "page_multiplier": 1.15 },
      "8.5x11":  { "label": "8.5 × 11 in (workbook)",      "page_multiplier": 1.90 }
    },
    "interior": {
      "bw":    { "label": "Black & white", "per_page": 0.45 },
      "color": { "label": "Full colour",   "per_page": 2.80 }
    },
    "paper": {
      "cream": { "label": "Cream 70 GSM", "per_page_extra": 0.00 },
      "white": { "label": "White 80 GSM", "per_page_extra": 0.05 }
    },
    "binding": {
      "paperback": { "label": "Paperback", "base": 30 },
      "hardcover": { "label": "Hardcover", "base": 140 }
    },
    "cover_finish": {
      "matte": { "label": "Matte", "extra": 0 },
      "gloss": { "label": "Gloss", "extra": 0 }
    }
  }'::jsonb,
  'Per-copy print rates (SAMPLE values). Used by the earnings calculator and checkout.'
),
(
  'fees',
  '{
    "platform_fee_per_copy": 15,
    "gateway_percent": 2,
    "gateway_gst_percent": 18
  }'::jsonb,
  'Platform fee per copy (Rs) and Razorpay charges (% of MRP, plus GST on the charge).'
),
(
  'shipping',
  '{
    "flat": 60,
    "free_above": 499
  }'::jsonb,
  'Shipping charged to readers (Rs). Free when the order subtotal is at or above free_above.'
)
on conflict (key) do nothing;

-- ===== 20261014000003_publishing.sql =====
-- Milestone 3: author publishing flow

-- Page size of the uploaded manuscript PDF (inches), read in the browser on upload.
-- Used to warn the author if it doesn't match the chosen book size.
alter table public.books
  add column manuscript_width_in  numeric(5, 2),
  add column manuscript_height_in numeric(5, 2);

-- Physical size of each trim option, for that comparison.
update public.settings
set value = jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(value,
  '{trim_sizes,5x8}',     value -> 'trim_sizes' -> '5x8'     || '{"width_in": 5,    "height_in": 8}'),
  '{trim_sizes,5.5x8.5}', value -> 'trim_sizes' -> '5.5x8.5' || '{"width_in": 5.5,  "height_in": 8.5}'),
  '{trim_sizes,a5}',      value -> 'trim_sizes' -> 'a5'      || '{"width_in": 5.83, "height_in": 8.27}'),
  '{trim_sizes,6x9}',     value -> 'trim_sizes' -> '6x9'     || '{"width_in": 6,    "height_in": 9}'),
  '{trim_sizes,8.5x11}',  value -> 'trim_sizes' -> '8.5x11'  || '{"width_in": 8.5,  "height_in": 11}')
where key = 'print_rates'
  and value -> 'trim_sizes' ?& array['5x8', '5.5x8.5', 'a5', '6x9', '8.5x11'];

-- ---------------------------------------------------------------------------
-- Storage: files live at <author_id>/<book_id>/<file>. Authors may only change
-- files of their own books, and only while the book is editable. Once a book is
-- in review or published, its files are frozen, so what the admin approved is
-- exactly what the printer prints.
-- ---------------------------------------------------------------------------
create function public.can_edit_book_files(object_name text)
returns boolean
language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from public.books b
    where b.id::text = (storage.foldername(object_name))[2]
      and b.author_id = auth.uid()
      and (storage.foldername(object_name))[1] = auth.uid()::text
      and b.status in ('draft', 'changes_requested', 'unpublished')
  )
$$;

drop policy "manuscripts: author uploads own folder" on storage.objects;
drop policy "manuscripts: author updates own folder" on storage.objects;
drop policy "manuscripts: author deletes own" on storage.objects;
drop policy "covers: author uploads own folder" on storage.objects;
drop policy "covers: author updates own folder" on storage.objects;
drop policy "covers: author deletes own" on storage.objects;

create policy "manuscripts: author uploads to editable book" on storage.objects
  for insert to authenticated with check (bucket_id = 'manuscripts' and public.can_edit_book_files(name));
create policy "manuscripts: author replaces in editable book" on storage.objects
  for update to authenticated using (bucket_id = 'manuscripts' and public.can_edit_book_files(name));
create policy "manuscripts: author deletes from editable book" on storage.objects
  for delete to authenticated using (bucket_id = 'manuscripts' and public.can_edit_book_files(name));

create policy "covers: author uploads to editable book" on storage.objects
  for insert to authenticated with check (bucket_id = 'covers' and public.can_edit_book_files(name));
create policy "covers: author replaces in editable book" on storage.objects
  for update to authenticated using (bucket_id = 'covers' and public.can_edit_book_files(name));
create policy "covers: author deletes from editable book" on storage.objects
  for delete to authenticated using (bucket_id = 'covers' and public.can_edit_book_files(name));
-- Replacing a file ("upsert") also needs read access through the API.
create policy "covers: author reads own folder" on storage.objects
  for select to authenticated using (
    bucket_id = 'covers' and (storage.foldername(name))[1] = auth.uid()::text
  );

-- ===== 20261014000004_print_cover.sql =====
-- Split the cover in two:
--   cover_path        front cover IMAGE in the public "covers" bucket (shown in the bookstore)
--   print_cover_path  full-wrap print PDF (back + spine + front) in the private "manuscripts" bucket
alter table public.books
  add column print_cover_path      text,
  add column print_cover_width_in  numeric(5, 2),
  add column print_cover_height_in numeric(5, 2);

-- The public bucket now only takes images
update storage.buckets
set allowed_mime_types = array['image/jpeg', 'image/png', 'image/webp']
where id = 'covers';

-- Spine thickness per page (mm) for each paper, and bleed (inches) around the full cover.
-- SAMPLE values: ask the printer for their exact paper thickness.
update public.settings
set value = jsonb_set(
      jsonb_set(
        jsonb_set(value, '{paper,cream}', value -> 'paper' -> 'cream' || '{"spine_mm_per_page": 0.055}'),
        '{paper,white}', value -> 'paper' -> 'white' || '{"spine_mm_per_page": 0.06}'),
      '{cover_bleed_in}', '0.125')
where key = 'print_rates'
  and value -> 'paper' ?& array['cream', 'white'];

-- ===== 20261014000005_admin.sql =====
-- Milestone 4: admin

-- Orders that count towards an author's earnings (payment received, not cancelled)
create function public.is_earning_status(s public.order_status)
returns boolean language sql immutable as $$
  select s in ('paid', 'printing', 'printed', 'shipped', 'delivered')
$$;

-- What each author has earned, been paid, and is still owed.
-- security_invoker: the reader's own RLS rules apply, so an author sees only
-- their own row and an admin sees everyone.
create view public.author_balances
with (security_invoker = true) as
select
  p.id as author_id,
  p.full_name,
  p.phone,
  p.payout_upi,
  coalesce(e.earned, 0)::numeric(12, 2)  as earned,
  coalesce(e.copies, 0)::integer          as copies_sold,
  coalesce(pp.paid, 0)::numeric(12, 2)    as paid,
  (coalesce(e.earned, 0) - coalesce(pp.paid, 0))::numeric(12, 2) as balance
from public.profiles p
left join (
  select oi.author_id, sum(oi.author_earning * oi.quantity) as earned, sum(oi.quantity) as copies
  from public.order_items oi
  join public.orders o on o.id = oi.order_id
  where public.is_earning_status(o.status)
  group by oi.author_id
) e on e.author_id = p.id
left join (
  select author_id, sum(amount) as paid
  from public.payouts
  where status = 'paid'
  group by author_id
) pp on pp.author_id = p.id
where p.role = 'author' or e.earned is not null;

-- "Who did this" columns should not block deleting a user account; just forget the name.
alter table public.settings drop constraint settings_updated_by_fkey,
  add constraint settings_updated_by_fkey foreign key (updated_by) references public.profiles (id) on delete set null;
alter table public.books drop constraint books_reviewed_by_fkey,
  add constraint books_reviewed_by_fkey foreign key (reviewed_by) references public.profiles (id) on delete set null;
alter table public.payouts drop constraint payouts_created_by_fkey,
  add constraint payouts_created_by_fkey foreign key (created_by) references public.profiles (id) on delete set null;

-- ===== 20261014000006_orders.sql =====
-- Milestone 5: checkout and printing

alter table public.orders
  add column payment_mode text check (payment_mode in ('razorpay', 'mock')),
  add column accepted_at  timestamptz;  -- printer started printing

-- Fast lookups for the printer queue and the payment webhook
create index orders_printer_status_idx on public.orders (printer_id, status);

-- Open jobs per printer, used to share new orders fairly between printers
create view public.printer_load
with (security_invoker = true) as
select p.id as printer_id, p.state, p.active,
  count(o.id) filter (where o.status in ('paid', 'printing', 'printed')) as open_jobs
from public.printers p
left join public.orders o on o.printer_id = p.id
group by p.id;

-- ===== 20261014000007_author_stats.sql =====
-- Milestone 6: author dashboard numbers.
-- Authors may not read the orders table (it holds buyers' names, phones and
-- addresses). These functions give an author only their OWN sales, and only
-- the parts they need: month, city, quantity, earnings and status.
-- They count paid orders only (paid → delivered), never unpaid or cancelled ones.

-- Copies sold and earnings per month, last `months` months including this one
create function public.my_sales_by_month(months int default 12)
returns table (month date, copies bigint, earnings numeric)
language sql stable security definer set search_path = public as $$
  with m as (
    select generate_series(
      date_trunc('month', now() at time zone 'Asia/Kolkata') - make_interval(months => greatest(months, 1) - 1),
      date_trunc('month', now() at time zone 'Asia/Kolkata'),
      interval '1 month'
    )::date as month
  )
  select m.month,
         coalesce(sum(oi.quantity), 0)::bigint,
         coalesce(sum(oi.quantity * oi.author_earning), 0)::numeric(12, 2)
  from m
  left join public.orders o
    on date_trunc('month', o.paid_at at time zone 'Asia/Kolkata')::date = m.month
   and public.is_earning_status(o.status)
  left join public.order_items oi
    on oi.order_id = o.id and oi.author_id = auth.uid()
  group by m.month
  order by m.month
$$;

-- Copies sold per delivery city (all time, or since `since`)
create function public.my_sales_by_city(since timestamptz default null)
returns table (city text, state text, copies bigint, earnings numeric)
language sql stable security definer set search_path = public as $$
  select initcap(trim(o.ship_city)), o.ship_state,
         sum(oi.quantity)::bigint, sum(oi.quantity * oi.author_earning)::numeric(12, 2)
  from public.order_items oi
  join public.orders o on o.id = oi.order_id
  where oi.author_id = auth.uid()
    and public.is_earning_status(o.status)
    and (since is null or o.paid_at >= since)
  group by 1, 2
  order by 3 desc, 1
$$;

-- Copies and earnings per book (all time)
create function public.my_sales_by_book()
returns table (book_id uuid, copies bigint, earnings numeric)
language sql stable security definer set search_path = public as $$
  select oi.book_id, sum(oi.quantity)::bigint, sum(oi.quantity * oi.author_earning)::numeric(12, 2)
  from public.order_items oi
  join public.orders o on o.id = oi.order_id
  where oi.author_id = auth.uid() and public.is_earning_status(o.status)
  group by oi.book_id
$$;

-- Recent orders of the author's books, for tracking (no buyer name, phone or address)
create function public.my_book_orders(max_rows int default 50, skip int default 0)
returns table (
  order_item_id uuid, order_number text, paid_at timestamptz, status public.order_status,
  ship_city text, ship_state text, book_title text, quantity int, earning numeric,
  shipped_at timestamptz, delivered_at timestamptz, total_count bigint
)
language sql stable security definer set search_path = public as $$
  select oi.id, o.order_number, o.paid_at, o.status, initcap(trim(o.ship_city)), o.ship_state,
         b.title, oi.quantity, (oi.quantity * oi.author_earning)::numeric(12, 2),
         o.shipped_at, o.delivered_at, count(*) over ()
  from public.order_items oi
  join public.orders o on o.id = oi.order_id
  join public.books b on b.id = oi.book_id
  where oi.author_id = auth.uid() and public.is_earning_status(o.status)
  order by o.paid_at desc
  limit least(greatest(max_rows, 1), 200) offset greatest(skip, 0)
$$;

-- The author's own totals. (The author_balances view can't be used by authors:
-- it reads the orders table, which only admins may see in full.)
create function public.my_balance()
returns table (earned numeric, copies_sold bigint, paid numeric, balance numeric)
language sql stable security definer set search_path = public as $$
  with e as (
    select coalesce(sum(oi.quantity * oi.author_earning), 0) as earned, coalesce(sum(oi.quantity), 0) as copies
    from public.order_items oi
    join public.orders o on o.id = oi.order_id
    where oi.author_id = auth.uid() and public.is_earning_status(o.status)
  ), p as (
    select coalesce(sum(amount), 0) as paid from public.payouts where author_id = auth.uid() and status = 'paid'
  )
  select e.earned::numeric(12, 2), e.copies::bigint, p.paid::numeric(12, 2), (e.earned - p.paid)::numeric(12, 2)
  from e, p
$$;

-- Only logged-in users may call these (each returns the caller's own data)
revoke execute on function public.my_sales_by_month(int) from public, anon;
revoke execute on function public.my_sales_by_city(timestamptz) from public, anon;
revoke execute on function public.my_sales_by_book() from public, anon;
revoke execute on function public.my_book_orders(int, int) from public, anon;
revoke execute on function public.my_balance() from public, anon;
grant execute on function public.my_balance() to authenticated;
grant execute on function public.my_sales_by_month(int) to authenticated;
grant execute on function public.my_sales_by_city(timestamptz) to authenticated;
grant execute on function public.my_sales_by_book() to authenticated;
grant execute on function public.my_book_orders(int, int) to authenticated;

