-- ===========================================================================
-- Pro analytics (real sales only) and campaign stats. Pro is checked here, not just in the UI.
-- ===========================================================================
create function public.my_sales_series(p_from date, p_to date, p_grain text default 'day')
returns table (period date, book_id uuid, copies bigint, earnings numeric)
language plpgsql stable security definer set search_path = public as $$
begin
  if not public.has_active_pro(auth.uid()) then raise exception 'PRO_REQUIRED'; end if;
  if p_grain not in ('day', 'week', 'month') then raise exception 'bad grain'; end if;
  return query
  select date_trunc(p_grain, o.paid_at at time zone 'Asia/Kolkata')::date, oi.book_id,
         sum(oi.quantity)::bigint, sum(public.line_earning(oi))::numeric(12, 2)
  from public.order_items oi
  join public.orders o on o.id = oi.order_id
  where oi.author_id = auth.uid() and oi.reversed_at is null and public.is_earning_status(o.status)
    and (o.paid_at at time zone 'Asia/Kolkata')::date between p_from and p_to
  group by 1, 2
  order by 1, 2;
end $$;

create function public.my_campaign_stats()
returns table (link_id uuid, code text, label text, book_id uuid, archived boolean, created_at timestamptz,
               clicks bigint, orders bigint, copies bigint)
language plpgsql stable security definer set search_path = public as $$
begin
  if not public.has_active_pro(auth.uid()) then raise exception 'PRO_REQUIRED'; end if;
  return query
  select l.id, l.code, l.label, l.book_id, l.archived, l.created_at,
         (select count(*) from public.campaign_clicks c where c.link_id = l.id),
         (select count(distinct o.id) from public.orders o join public.order_items oi on oi.order_id = o.id
            where o.campaign_link_id = l.id and oi.book_id = l.book_id and public.is_earning_status(o.status)),
         (select coalesce(sum(oi.quantity), 0) from public.orders o join public.order_items oi on oi.order_id = o.id
            where o.campaign_link_id = l.id and oi.book_id = l.book_id and oi.reversed_at is null and public.is_earning_status(o.status))::bigint
  from public.campaign_links l
  where l.author_id = auth.uid()
  order by l.created_at desc;
end $$;

revoke execute on function public.my_sales_series(date, date, text) from public, anon;
revoke execute on function public.my_campaign_stats() from public, anon;
grant execute on function public.my_sales_series(date, date, text) to authenticated;
grant execute on function public.my_campaign_stats() to authenticated;

-- ===========================================================================
-- Admin finance summary. Book sales value is NOT platform income.
-- ===========================================================================
create function public.admin_finance(p_from timestamptz, p_to timestamptz)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  result jsonb;
begin
  if not public.is_admin() then raise exception 'ADMIN_ONLY'; end if;
  with lines as (
    select oi.*, o.status as order_status
    from public.order_items oi join public.orders o on o.id = oi.order_id
    where o.paid_at >= p_from and o.paid_at < p_to and public.is_earning_status(o.status) and oi.reversed_at is null
  ), ord as (
    select * from public.orders o
    where o.paid_at >= p_from and o.paid_at < p_to and o.status <> 'pending_payment'
  )
  select jsonb_build_object(
    'book_sales_value', coalesce((select sum(unit_price * quantity) from lines), 0),
    'print_costs',      coalesce((select sum(coalesce(print_cost_total, print_cost * quantity)) from lines), 0),
    'commission',       coalesce((select sum(coalesce(commission, platform_fee * quantity)) from lines), 0),
    'commission_gst',   coalesce((select sum(coalesce(commission_gst, 0)) from lines), 0),
    'gateway_costs',    coalesce((select sum(coalesce(gateway_allocated, payment_fee * quantity)) from lines), 0),
    'author_earnings',  coalesce((select sum(public.line_earning(l::public.order_items)) from lines l), 0),
    'shipping_collected', coalesce((select sum(shipping) from ord where public.is_earning_status(status)), 0),
    'shipping_promotions', coalesce((select sum(shipping_discount) from ord where public.is_earning_status(status)), 0),
    'book_refunds',     coalesce((select sum(refund_amount) from ord where refund_status in ('processed', 'pending')), 0),
    'service_revenue',  coalesce((select sum(base_paise) from public.payments where purpose = 'service' and status in ('paid', 'partially_refunded') and paid_at >= p_from and paid_at < p_to), 0) / 100.0,
    'service_gst',      coalesce((select sum(gst_paise) from public.payments where purpose = 'service' and status in ('paid', 'partially_refunded') and paid_at >= p_from and paid_at < p_to), 0) / 100.0,
    'subscription_revenue', coalesce((select sum(base_paise) from public.payments where purpose = 'subscription' and status in ('paid', 'partially_refunded') and paid_at >= p_from and paid_at < p_to), 0) / 100.0,
    'subscription_gst', coalesce((select sum(gst_paise) from public.payments where purpose = 'subscription' and status in ('paid', 'partially_refunded') and paid_at >= p_from and paid_at < p_to), 0) / 100.0,
    'other_refunds',    coalesce((select sum(refunded_paise) from public.payments where refunded_at >= p_from and refunded_at < p_to), 0) / 100.0,
    'author_liability', coalesce((select sum(greatest(balance, 0)) from public.author_balances), 0)
  ) into result;
  return result;
end $$;
revoke execute on function public.admin_finance(timestamptz, timestamptz) from public, anon;
grant execute on function public.admin_finance(timestamptz, timestamptz) to authenticated;

-- ===========================================================================
-- Service payments: mark a quote paid and queue the work. Idempotent.
-- ===========================================================================
create function public.pay_service_quote(p_payment uuid, p_razorpay_payment_id text, p_fee_paise integer default null)
returns public.service_orders language plpgsql security definer set search_path = public as $$
declare
  pay public.payments;
  q public.service_quotes;
  so public.service_orders;
begin
  select * into pay from public.payments where id = p_payment for update;
  if pay.id is null or pay.purpose <> 'service' then raise exception 'service payment not found'; end if;
  select * into q from public.service_quotes where id = pay.service_quote_id for update;
  select * into so from public.service_orders where id = q.service_order_id for update;
  if pay.status = 'paid' then return so; end if;            -- already done

  update public.payments
     set status = 'paid', paid_at = now(), razorpay_payment_id = coalesce(p_razorpay_payment_id, razorpay_payment_id),
         fee_paise = coalesce(p_fee_paise, fee_paise),
         receipt_number = coalesce(receipt_number, 'EIP-R-' || lpad(nextval('public.receipt_seq')::text, 6, '0'))
   where id = p_payment;
  update public.service_quotes set status = 'paid' where id = q.id;

  if so.status = 'payment_pending' then
    update public.service_orders
       set status = 'queued',
           revisions_allowed = case when q.kind = 'additional' then revisions_allowed + q.revisions else q.revisions end
     where id = so.id
    returning * into so;
    insert into public.service_events (service_order_id, from_status, to_status, note)
    values (so.id, 'payment_pending', 'queued', 'Payment received. Work starts once requirements are complete.');
  else
    -- Paid after the order was cancelled: keep the record so admin can refund it
    insert into public.service_events (service_order_id, from_status, to_status, note)
    values (so.id, so.status, so.status, 'Payment received for an order that is no longer awaiting payment. Refund needed.');
  end if;
  return so;
end $$;
revoke execute on function public.pay_service_quote(uuid, text, integer) from public, anon, authenticated;

-- ===== 20261017000011_service_portfolio.sql =====
-- Service portfolio update.
-- 1. New catalogue versions with clearer deliverables, scope and exclusions, and the bundle shown as
--    "Book Design & Launch Bundle". Service codes stay the same. Prices, GST and revision rounds are
--    copied from the current version (never overwritten), and existing orders keep the version they
--    were placed on.
-- 2. Bundle upgrades: a bundle request can replace earlier requests for parts of it. Admin reviews what
--    was paid and issues an itemised quote; unpaid earlier requests are closed when the upgrade is paid,
--    so nothing is charged twice.

insert into public.service_catalog
  (code, version, name, pricing, price_paise, min_paise, max_paise, gst_percent, revision_rounds,
   deliverables, scope, exclusions, requires, sort, active)
select c.code, c.version + 1, v.name, c.pricing, c.price_paise, c.min_paise, c.max_paise, c.gst_percent, c.revision_rounds,
       v.deliverables, v.scope, v.exclusions, c.requires, c.sort, c.active
from public.current_service_catalog c
join (values
  ('basic_cover', 'Basic Book Cover',
   array['One cover concept',
         'Front, spine and back-cover design',
         'Final print-ready cover PDF',
         'Front-cover image for your book page',
         'One book mockup image'],
   'One cover concept developed into a full paperback wrap. Before the final wrap we confirm your printer''s trim size, bleed, paper and final page count, so the spine is exact.',
   array['Editing and proofreading', 'Printing and shipping', 'Paid advertising', 'Guaranteed sales',
         'Custom illustration', 'Stock images beyond our licensed library', 'Editable source files unless agreed']),
  ('formatting', 'Interior Formatting',
   array['Title and copyright-page layout',
         'Contents page where appropriate',
         'Chapter headings',
         'Consistent fonts, margins and page numbers',
         'Print-ready interior PDF'],
   'Typesetting your finished manuscript into a print-ready interior. We quote a fixed price after reviewing your manuscript''s length and complexity.',
   array['Editing and proofreading', 'Rewriting or translation', 'Printing and shipping', 'Paid advertising', 'Guaranteed sales',
         'Complex tables, equations or heavy illustrations unless quoted']),
  ('launch_kit', 'Launch Kit',
   array['Five creatives: cover reveal, launch announcement, quote card, book introduction and buy-now post',
         'Five captions, one for each creative',
         'Feed and story versions of each creative'],
   'Five coordinated designs for your launch, each supplied in two sizes (feed and story). That is five creatives in two formats, not ten different designs.',
   array['Editing and proofreading', 'Printing and shipping', 'Paid advertising', 'Guaranteed sales',
         'Posting or managing your accounts', 'Video']),
  ('bundle', 'Book Design & Launch Bundle',
   array['Basic cover: one concept with front, spine and back',
         'Interior formatting up to 200 final pages of simple text',
         'Five launch creatives with captions, in feed and story sizes',
         'Two consolidated revision rounds'],
   'Cover, formatting and launch creatives together. We check your manuscript length and files before you pay; if it is longer than 200 pages or complex, you get a revised quote first.',
   array['Editing and proofreading', 'Printing and shipping', 'Paid advertising', 'Guaranteed sales',
         'Complex tables, equations, heavy illustrations or custom illustration', 'Marketplace distribution',
         'New manuscript content after approval (needs a revised quote)'])
) as v(code, name, deliverables, scope, exclusions) on v.code = c.code;

-- Earlier requests a bundle upgrade replaces, and itemised quote lines (bundle price, credits)
alter table public.service_orders add column upgrade_from uuid[];
alter table public.service_quotes add column line_items jsonb;
create index service_orders_upgrade_idx on public.service_orders using gin (upgrade_from);

-- Same as before, plus: when a bundle upgrade is paid, earlier requests it replaces that were never paid
-- are closed (not charged). Paid earlier requests stay as they are; admin credits them in the quote.
create or replace function public.pay_service_quote(p_payment uuid, p_razorpay_payment_id text, p_fee_paise integer default null)
returns public.service_orders language plpgsql security definer set search_path = public as $$
declare
  pay public.payments;
  q public.service_quotes;
  so public.service_orders;
  prior public.service_orders;
begin
  select * into pay from public.payments where id = p_payment for update;
  if pay.id is null or pay.purpose <> 'service' then raise exception 'service payment not found'; end if;
  select * into q from public.service_quotes where id = pay.service_quote_id for update;
  select * into so from public.service_orders where id = q.service_order_id for update;
  if pay.status = 'paid' then return so; end if;            -- already done

  update public.payments
     set status = 'paid', paid_at = now(), razorpay_payment_id = coalesce(p_razorpay_payment_id, razorpay_payment_id),
         fee_paise = coalesce(p_fee_paise, fee_paise),
         receipt_number = coalesce(receipt_number, 'EIP-R-' || lpad(nextval('public.receipt_seq')::text, 6, '0'))
   where id = p_payment;
  update public.service_quotes set status = 'paid' where id = q.id;

  if so.status = 'payment_pending' then
    update public.service_orders
       set status = 'queued',
           revisions_allowed = case when q.kind = 'additional' then revisions_allowed + q.revisions else q.revisions end
     where id = so.id
    returning * into so;
    insert into public.service_events (service_order_id, from_status, to_status, note)
    values (so.id, 'payment_pending', 'queued', 'Payment received. Work starts once requirements are complete.');

    if so.upgrade_from is not null then
      for prior in
        select * from public.service_orders
         where id = any(so.upgrade_from)
           and status in ('requirements_pending', 'scope_review', 'quote_awaiting_acceptance', 'payment_pending')
         for update
      loop
        update public.service_orders
           set status = 'cancelled', cancelled_at = now(), cancel_reason = 'Replaced by bundle upgrade ' || so.order_number
         where id = prior.id;
        update public.service_quotes set status = 'superseded' where service_order_id = prior.id and status in ('issued', 'accepted');
        insert into public.service_events (service_order_id, from_status, to_status, note)
        values (prior.id, prior.status, 'cancelled', 'Replaced by bundle upgrade ' || so.order_number || '. Not charged.');
      end loop;
    end if;
  else
    -- Paid after the order was cancelled: keep the record so admin can refund it
    insert into public.service_events (service_order_id, from_status, to_status, note)
    values (so.id, so.status, so.status, 'Payment received for an order that is no longer awaiting payment. Refund needed.');
  end if;
  return so;
end $$;
revoke execute on function public.pay_service_quote(uuid, text, integer) from public, anon, authenticated;

-- ===== 20261018000012_articles.sql =====
-- Author Articles: longer essays, reflections, writing advice and authorised excerpts.
-- Also the community basics Articles needs and the app didn't have yet: public author profiles
-- (handle + bio), follows, in-app notifications with a preference, blocking, reports, moderation
-- and account restrictions.
--
-- Articles are written and stored by the server (service role). Row Level Security only lets the
-- public read published, visible articles and their visible comments; drafts, bookmarks, likes,
-- views and notifications are never readable through the public API.

-- ---------------------------------------------------------------------------
-- Public author profile fields and the notification preference
-- ---------------------------------------------------------------------------
alter table public.profiles
  add column handle text unique check (handle ~ '^[a-z0-9][a-z0-9-]{2,40}$'),
  add column bio text check (char_length(bio) <= 600),
  add column notify_new_articles boolean not null default true;

-- Existing authors get a stable handle for their public page (name + short id; Hindi-only names fall back to "author")
update public.profiles
   set handle = left(coalesce(nullif(trim(both '-' from lower(regexp_replace(coalesce(full_name, ''), '[^a-zA-Z0-9]+', '-', 'g'))), ''), 'author'), 30)
                || '-' || substr(replace(id::text, '-', ''), 1, 6)
 where role in ('author', 'admin') and handle is null;

-- New authors get one automatically once they have a name (onboarding, or "I want to publish")
create or replace function public.profile_default_handle()
returns trigger language plpgsql set search_path = public as $$
begin
  if new.handle is null and new.role in ('author', 'admin') and coalesce(trim(new.full_name), '') <> '' then
    new.handle := left(coalesce(nullif(trim(both '-' from lower(regexp_replace(new.full_name, '[^a-zA-Z0-9]+', '-', 'g'))), ''), 'author'), 30)
                  || '-' || substr(md5(new.id::text || clock_timestamp()::text), 1, 6);
  end if;
  return new;
end $$;
create trigger profiles_default_handle before insert or update of role, full_name on public.profiles
  for each row execute function public.profile_default_handle();

-- What the public may see of an author: name, handle and bio only (never phone or address)
create view public.public_authors with (security_invoker = false) as
  select id, handle, full_name, bio from public.profiles where role in ('author', 'admin') and handle is not null;
grant select on public.public_authors to anon, authenticated;

-- Admin-only: accounts restricted from posting (articles, comments, reports) after abuse
create table public.account_restrictions (
  user_id     uuid primary key references public.profiles (id) on delete cascade,
  reason      text not null check (char_length(reason) between 3 and 500),
  until       timestamptz,                    -- null = until lifted
  created_by  uuid references public.profiles (id) on delete set null,
  created_at  timestamptz not null default now()
);
alter table public.account_restrictions enable row level security;
create policy "restrictions: admin" on public.account_restrictions for all using (public.is_admin()) with check (public.is_admin());

-- ---------------------------------------------------------------------------
-- Articles
-- ---------------------------------------------------------------------------
create table public.articles (
  id                  uuid primary key default gen_random_uuid(),
  short_id            text not null unique default lower(substr(md5(gen_random_uuid()::text), 1, 8)),  -- stable in the URL
  slug                text not null default '' check (char_length(slug) <= 90),   -- readable part; may change, links still work
  author_id           uuid not null references public.profiles (id) on delete cascade,
  title               text not null default '' check (char_length(title) <= 150),
  excerpt             text not null default '' check (char_length(excerpt) <= 300),
  cover_path          text,
  cover_alt           text check (char_length(cover_alt) <= 200),
  language            text not null default 'en' check (language in ('en', 'hi')),
  topic               text check (topic in ('essay', 'reflection', 'writing-advice', 'book-excerpt', 'behind-the-book', 'other')),
  tags                text[] not null default '{}' check (cardinality(tags) <= 5),
  body_md             text not null default '' check (char_length(body_md) <= 40000),   -- source the author edits
  body                jsonb not null default '[]',                                        -- parsed, safe blocks the page renders
  word_count          integer not null default 0,
  related_book_id     uuid references public.books (id) on delete set null,
  status              text not null default 'draft' check (status in ('draft', 'published', 'unpublished')),
  moderation          text not null default 'visible' check (moderation in ('visible', 'hidden', 'removed')),
  moderation_reason   text,
  rights_confirmed_at timestamptz,
  first_published_at  timestamptz,           -- set once; followers are notified only then
  published_at        timestamptz,
  content_updated_at  timestamptz,           -- last edit after publishing (shown as "Updated")
  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now(),
  check (status = 'draft' or (rights_confirmed_at is not null and published_at is not null))
);
create index articles_public_idx on public.articles (published_at desc) where status = 'published' and moderation = 'visible';
create index articles_author_idx on public.articles (author_id, updated_at desc);
create index articles_topic_idx on public.articles (topic, published_at desc) where status = 'published' and moderation = 'visible';
create trigger articles_touch before update on public.articles for each row execute function public.touch_updated_at();
alter table public.articles enable row level security;
create policy "articles: public reads published" on public.articles for select
  using (status = 'published' and moderation = 'visible');
create policy "articles: author reads own" on public.articles for select using (author_id = auth.uid());
create policy "articles: admin" on public.articles for all using (public.is_admin()) with check (public.is_admin());

create function public.article_is_public(p_article uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.articles where id = p_article and status = 'published' and moderation = 'visible')
$$;

-- One like and one bookmark per account per article (database-enforced)
create table public.article_likes (
  article_id uuid not null references public.articles (id) on delete cascade,
  user_id    uuid not null references public.profiles (id) on delete cascade,
  created_at timestamptz not null default now(),
  primary key (article_id, user_id)
);
alter table public.article_likes enable row level security;
create policy "likes: own" on public.article_likes for select using (user_id = auth.uid());

create table public.article_bookmarks (
  article_id uuid not null references public.articles (id) on delete cascade,
  user_id    uuid not null references public.profiles (id) on delete cascade,
  created_at timestamptz not null default now(),
  primary key (article_id, user_id)
);
create index article_bookmarks_user_idx on public.article_bookmarks (user_id, created_at desc);
alter table public.article_bookmarks enable row level security;
create policy "bookmarks: own" on public.article_bookmarks for select using (user_id = auth.uid());

-- Flat comments
create table public.article_comments (
  id          uuid primary key default gen_random_uuid(),
  article_id  uuid not null references public.articles (id) on delete cascade,
  user_id     uuid not null references public.profiles (id) on delete cascade,
  body        text not null check (char_length(body) between 1 and 2000),
  moderation  text not null default 'visible' check (moderation in ('visible', 'hidden', 'removed')),
  edited_at   timestamptz,
  created_at  timestamptz not null default now()
);
create index article_comments_article_idx on public.article_comments (article_id, created_at);
create index article_comments_user_idx on public.article_comments (user_id, created_at desc);
alter table public.article_comments enable row level security;
create policy "comments: public reads visible" on public.article_comments for select
  using (moderation = 'visible' and public.article_is_public(article_id));
create policy "comments: admin" on public.article_comments for all using (public.is_admin()) with check (public.is_admin());

-- Views: once per signed-in reader or browser per article per day. Not unique people.
create table public.article_views (
  article_id uuid not null references public.articles (id) on delete cascade,
  viewer_key text not null,
  day        date not null default (now() at time zone 'Asia/Kolkata')::date,
  primary key (article_id, viewer_key, day)
);
create index article_views_day_idx on public.article_views (article_id, day);
alter table public.article_views enable row level security;

-- Clicks on the related-book card ("View book"), deduplicated the same way
create table public.article_book_clicks (
  article_id uuid not null references public.articles (id) on delete cascade,
  viewer_key text not null,
  day        date not null default (now() at time zone 'Asia/Kolkata')::date,
  book_id    uuid references public.books (id) on delete set null,
  primary key (article_id, viewer_key, day)
);
alter table public.article_book_clicks enable row level security;

-- ---------------------------------------------------------------------------
-- Follows, blocks, notifications
-- ---------------------------------------------------------------------------
create table public.follows (
  follower_id uuid not null references public.profiles (id) on delete cascade,
  author_id   uuid not null references public.profiles (id) on delete cascade,
  created_at  timestamptz not null default now(),
  primary key (follower_id, author_id),
  check (follower_id <> author_id)
);
create index follows_author_idx on public.follows (author_id);
alter table public.follows enable row level security;
create policy "follows: own" on public.follows for select using (follower_id = auth.uid());

create table public.user_blocks (
  blocker_id uuid not null references public.profiles (id) on delete cascade,
  blocked_id uuid not null references public.profiles (id) on delete cascade,
  created_at timestamptz not null default now(),
  primary key (blocker_id, blocked_id),
  check (blocker_id <> blocked_id)
);
create index user_blocks_blocked_idx on public.user_blocks (blocked_id);
alter table public.user_blocks enable row level security;
create policy "blocks: own" on public.user_blocks for select using (blocker_id = auth.uid());

create table public.notifications (
  id          uuid primary key default gen_random_uuid(),
  user_id     uuid not null references public.profiles (id) on delete cascade,
  kind        text not null check (kind in ('new_article')),
  actor_id    uuid references public.profiles (id) on delete set null,
  article_id  uuid references public.articles (id) on delete cascade,
  title       text not null,
  link        text not null,
  read_at     timestamptz,
  created_at  timestamptz not null default now(),
  unique (user_id, kind, article_id)          -- never the same notification twice
);
create index notifications_user_idx on public.notifications (user_id, created_at desc);
alter table public.notifications enable row level security;
create policy "notifications: own" on public.notifications for select using (user_id = auth.uid());

-- ---------------------------------------------------------------------------
-- Reports and moderation log
-- ---------------------------------------------------------------------------
create table public.content_reports (
  id           uuid primary key default gen_random_uuid(),
  reporter_id  uuid not null references public.profiles (id) on delete cascade,
  target_type  text not null check (target_type in ('article', 'comment')),
  target_id    uuid not null,
  reason       text not null check (reason in ('spam', 'abuse', 'hate', 'copyright', 'private-info', 'other')),
  details      text check (char_length(details) <= 1000),
  status       text not null default 'open' check (status in ('open', 'actioned', 'dismissed')),
  resolved_by  uuid references public.profiles (id) on delete set null,
  resolved_at  timestamptz,
  created_at   timestamptz not null default now()
);
create unique index content_reports_once_idx on public.content_reports (reporter_id, target_type, target_id) where status = 'open';
create index content_reports_open_idx on public.content_reports (status, created_at);
alter table public.content_reports enable row level security;
create policy "reports: admin" on public.content_reports for all using (public.is_admin()) with check (public.is_admin());

create table public.moderation_actions (
  id           uuid primary key default gen_random_uuid(),
  actor_id     uuid references public.profiles (id) on delete set null,
  target_type  text not null check (target_type in ('article', 'comment', 'user')),
  target_id    uuid not null,
  action       text not null check (action in ('hide', 'restore', 'remove', 'restrict', 'unrestrict', 'dismiss')),
  reason       text not null check (char_length(reason) between 3 and 500),
  created_at   timestamptz not null default now()
);
create index moderation_actions_target_idx on public.moderation_actions (target_type, target_id, created_at desc);
alter table public.moderation_actions enable row level security;
create policy "moderation: admin" on public.moderation_actions for all using (public.is_admin()) with check (public.is_admin());

-- ---------------------------------------------------------------------------
-- Publishing: set the dates and, on the first publication only, notify followers once
-- ---------------------------------------------------------------------------
create function public.publish_article(p_article uuid, p_author uuid)
returns table (first_time boolean, notified integer)
language plpgsql security definer set search_path = public as $$
declare
  a public.articles;
  n integer := 0;
  first boolean;
begin
  select * into a from public.articles where id = p_article and author_id = p_author for update;
  if a.id is null then raise exception 'ARTICLE_NOT_FOUND'; end if;
  if a.moderation <> 'visible' then raise exception 'ARTICLE_MODERATED'; end if;
  if a.rights_confirmed_at is null then raise exception 'RIGHTS_NOT_CONFIRMED'; end if;
  first := a.first_published_at is null;
  update public.articles
     set status = 'published',
         published_at = coalesce(a.first_published_at, now()),
         first_published_at = coalesce(a.first_published_at, now())
   where id = a.id;
  if first then
    insert into public.notifications (user_id, kind, actor_id, article_id, title, link)
    select f.follower_id, 'new_article', a.author_id, a.id,
           coalesce((select full_name from public.profiles where id = a.author_id), 'An author') || ' published: ' || a.title,
           '/articles/' || a.short_id || case when a.slug <> '' then '-' || a.slug else '' end
      from public.follows f
      join public.profiles p on p.id = f.follower_id
     where f.author_id = a.author_id
       and p.notify_new_articles
       and not exists (select 1 from public.user_blocks b
                        where (b.blocker_id = f.follower_id and b.blocked_id = a.author_id)
                           or (b.blocker_id = a.author_id and b.blocked_id = f.follower_id))
    on conflict (user_id, kind, article_id) do nothing;
    get diagnostics n = row_count;
  end if;
  return query select first, n;
end $$;
revoke execute on function public.publish_article(uuid, uuid) from public, anon, authenticated;

-- ---------------------------------------------------------------------------
-- Article covers: public images, written only by the server after checks and re-encoding
-- ---------------------------------------------------------------------------
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('article-covers', 'article-covers', true, 2097152, array['image/webp'])
on conflict (id) do nothing;

-- Author page addresses (/authors/{handle}) stay stable: people can't change their handle themselves
create or replace function public.guard_profile_handle()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if new.handle is distinct from old.handle and auth.uid() is not null and not public.is_admin() then
    raise exception 'Profile handle cannot be changed here';
  end if;
  return new;
end $$;

drop trigger if exists profiles_guard_handle on public.profiles;
create trigger profiles_guard_handle before update of handle on public.profiles
  for each row execute function public.guard_profile_handle();

-- ===== 20261019000013_avatars_samples.sql =====
-- Profile photos and book "Read sample" pages.
--
-- Photos: people upload a photo; the server checks it, crops it square, re-encodes it as WebP (which drops
-- EXIF/GPS) and stores it in the public "avatars" bucket. Only the server writes there.
-- Samples: an author chooses a short run of pages from their own manuscript (at most 10% of the book, up to
-- 30 pages). The server copies just those pages into a new PDF in the public "book-samples" bucket. The
-- manuscript itself stays private.

alter table public.profiles
  add column avatar_path text check (char_length(avatar_path) <= 300);

-- Public author details now include the photo (still never phone or address)
create or replace view public.public_authors with (security_invoker = false) as
  select id, handle, full_name, bio, avatar_path from public.profiles where role in ('author', 'admin') and handle is not null;
grant select on public.public_authors to anon, authenticated;

alter table public.books
  add column sample_path  text check (char_length(sample_path) <= 300),
  add column sample_from  integer check (sample_from >= 1),
  add column sample_to    integer,
  add constraint books_sample_range check (
    (sample_path is null and sample_from is null and sample_to is null)
    or (sample_path is not null and sample_from is not null and sample_to >= sample_from and sample_to - sample_from < 30)
  );

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values
  ('avatars', 'avatars', true, 524288, array['image/webp']),
  ('book-samples', 'book-samples', true, 15728640, array['application/pdf'])
on conflict (id) do nothing;

-- ===== 20261020000014_community_versions_reviews.sql =====
-- Community updates, saved file versions, and verified-purchase reviews.
-- Additive only: no existing rows are changed except to record the current files as version 1.

-- ---------------------------------------------------------------------------
-- 1. Saved file versions
-- Every manuscript / print cover / cover image an author uploads is kept as its own file and listed here.
-- When our team approves a book, the versions it approved are pinned on the book; orders print those.
-- ---------------------------------------------------------------------------
create table public.book_file_versions (
  id           uuid primary key default gen_random_uuid(),
  book_id      uuid not null references public.books (id) on delete cascade,
  kind         text not null check (kind in ('manuscript', 'print_cover', 'cover')),
  version      integer not null check (version >= 1),
  path         text not null check (char_length(path) <= 300),
  page_count   integer,
  width_in     numeric(6, 2),
  height_in    numeric(6, 2),
  uploaded_by  uuid references public.profiles (id) on delete set null,
  created_at   timestamptz not null default now(),
  unique (book_id, kind, version)
);
create index book_file_versions_book_idx on public.book_file_versions (book_id, kind, version desc);
alter table public.book_file_versions enable row level security;
create policy "file versions: author reads own" on public.book_file_versions for select
  using (exists (select 1 from public.books b where b.id = book_id and b.author_id = auth.uid()));
create policy "file versions: admin" on public.book_file_versions for all using (public.is_admin()) with check (public.is_admin());

alter table public.books
  add column approved_files       jsonb,         -- {manuscript: {id, version, path}, print_cover: {...}, cover: {...}} pinned at approval
  add column approved_files_at    timestamptz,
  add column files_confirmed_at   timestamptz;   -- author confirmed the files they're submitting

-- Existing books: today's files become version 1, and live books count them as approved
insert into public.book_file_versions (book_id, kind, version, path, page_count, width_in, height_in, uploaded_by, created_at)
select b.id, 'manuscript', 1, b.manuscript_path, b.page_count, b.manuscript_width_in, b.manuscript_height_in, b.author_id, b.updated_at
  from public.books b where b.manuscript_path is not null;
insert into public.book_file_versions (book_id, kind, version, path, uploaded_by, created_at)
select b.id, 'print_cover', 1, b.print_cover_path, b.author_id, b.updated_at from public.books b where b.print_cover_path is not null;
insert into public.book_file_versions (book_id, kind, version, path, uploaded_by, created_at)
select b.id, 'cover', 1, b.cover_path, b.author_id, b.updated_at from public.books b where b.cover_path is not null;

update public.books b
   set approved_files = (
         select jsonb_object_agg(v.kind, jsonb_build_object('id', v.id, 'version', v.version, 'path', v.path))
           from public.book_file_versions v where v.book_id = b.id
       ),
       approved_files_at = coalesce(b.published_at, now())
 where b.status = 'published'
   and exists (select 1 from public.book_file_versions v where v.book_id = b.id);

-- ---------------------------------------------------------------------------
-- 2. Community: short updates from authors
-- ---------------------------------------------------------------------------
create table public.posts (
  id               uuid primary key default gen_random_uuid(),
  author_id        uuid not null references public.profiles (id) on delete cascade,
  body             text not null default '' check (char_length(body) <= 1000),
  image_path       text check (char_length(image_path) <= 300),
  image_alt        text check (char_length(image_alt) <= 200),
  related_book_id  uuid references public.books (id) on delete set null,
  status           text not null default 'draft' check (status in ('draft', 'published')),
  moderation       text not null default 'visible' check (moderation in ('visible', 'hidden', 'removed')),
  moderation_reason text,
  published_at     timestamptz,
  first_published_at timestamptz,
  edited_at        timestamptz,
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now(),
  check (status = 'draft' or (published_at is not null and char_length(trim(body)) >= 1))
);
create index posts_public_idx on public.posts (published_at desc) where status = 'published' and moderation = 'visible';
create index posts_author_idx on public.posts (author_id, created_at desc);
create trigger posts_touch before update on public.posts for each row execute function public.touch_updated_at();
alter table public.posts enable row level security;
create policy "posts: public reads published" on public.posts for select using (status = 'published' and moderation = 'visible');
create policy "posts: author reads own" on public.posts for select using (author_id = auth.uid());
create policy "posts: admin" on public.posts for all using (public.is_admin()) with check (public.is_admin());

create or replace function public.post_is_public(p uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.posts where id = p and status = 'published' and moderation = 'visible')
$$;

create table public.post_likes (
  post_id    uuid not null references public.posts (id) on delete cascade,
  user_id    uuid not null references public.profiles (id) on delete cascade,
  created_at timestamptz not null default now(),
  primary key (post_id, user_id)          -- one like per account
);
alter table public.post_likes enable row level security;
create policy "post likes: own" on public.post_likes for select using (user_id = auth.uid());

create table public.post_comments (
  id          uuid primary key default gen_random_uuid(),
  post_id     uuid not null references public.posts (id) on delete cascade,
  user_id     uuid not null references public.profiles (id) on delete cascade,
  body        text not null check (char_length(body) between 1 and 1000),
  moderation  text not null default 'visible' check (moderation in ('visible', 'hidden', 'removed')),
  edited_at   timestamptz,
  created_at  timestamptz not null default now()
);
create index post_comments_post_idx on public.post_comments (post_id, created_at);
create index post_comments_user_idx on public.post_comments (user_id, created_at desc);
alter table public.post_comments enable row level security;
create policy "post comments: public reads visible" on public.post_comments for select
  using (moderation = 'visible' and public.post_is_public(post_id));
create policy "post comments: admin" on public.post_comments for all using (public.is_admin()) with check (public.is_admin());

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('post-images', 'post-images', true, 2097152, array['image/webp'])
on conflict (id) do nothing;

-- Reports, moderation and notifications learn about posts
alter table public.content_reports drop constraint content_reports_target_type_check;
alter table public.content_reports add constraint content_reports_target_type_check
  check (target_type in ('article', 'comment', 'post', 'post_comment', 'review'));
alter table public.moderation_actions drop constraint moderation_actions_target_type_check;
alter table public.moderation_actions add constraint moderation_actions_target_type_check
  check (target_type in ('article', 'comment', 'user', 'post', 'post_comment', 'review'));

alter table public.notifications drop constraint notifications_kind_check;
alter table public.notifications add constraint notifications_kind_check check (kind in ('new_article', 'new_post'));
alter table public.notifications add column post_id uuid references public.posts (id) on delete cascade;
create unique index notifications_post_once_idx on public.notifications (user_id, kind, post_id) where post_id is not null;

alter table public.profiles add column notify_new_posts boolean not null default true;

-- First publication of an update notifies followers once (preference and blocks respected); later edits never do
create or replace function public.publish_post(p_post uuid, p_author uuid)
returns table (first_time boolean, notified integer)
language plpgsql security definer set search_path = public as $$
declare
  p public.posts;
  n integer := 0;
begin
  select * into p from public.posts where id = p_post for update;
  if not found or p.author_id <> p_author then raise exception 'POST_NOT_FOUND'; end if;
  if p.moderation <> 'visible' then raise exception 'POST_MODERATED'; end if;
  update public.posts
     set status = 'published',
         published_at = coalesce(published_at, now()),
         first_published_at = coalesce(first_published_at, now())
   where id = p_post;
  if p.first_published_at is null then
    insert into public.notifications (user_id, kind, actor_id, post_id, title, link)
    select f.follower_id, 'new_post', p_author, p_post, left(regexp_replace(p.body, '\s+', ' ', 'g'), 120), '/community/' || p_post
      from public.follows f
      join public.profiles pr on pr.id = f.follower_id
     where f.author_id = p_author
       and pr.notify_new_posts
       and not exists (select 1 from public.user_blocks ub
                        where (ub.blocker_id = f.follower_id and ub.blocked_id = p_author)
                           or (ub.blocker_id = p_author and ub.blocked_id = f.follower_id))
    on conflict do nothing;
    get diagnostics n = row_count;
  end if;
  return query select p.first_published_at is null, n;
end $$;
revoke execute on function public.publish_post(uuid, uuid) from public, anon, authenticated;

-- ---------------------------------------------------------------------------
-- 3. Verified-purchase reviews
-- Only a reader whose order with this book was delivered may review it, once per book.
-- ---------------------------------------------------------------------------
create table public.book_reviews (
  id          uuid primary key default gen_random_uuid(),
  book_id     uuid not null references public.books (id) on delete cascade,
  user_id     uuid not null references public.profiles (id) on delete cascade,
  rating      smallint not null check (rating between 1 and 5),
  body        text check (char_length(body) <= 1500),
  moderation  text not null default 'visible' check (moderation in ('visible', 'hidden', 'removed')),
  edited_at   timestamptz,
  created_at  timestamptz not null default now(),
  unique (book_id, user_id)
);
create index book_reviews_book_idx on public.book_reviews (book_id, created_at desc);
alter table public.book_reviews enable row level security;
create policy "reviews: public reads visible" on public.book_reviews for select
  using (moderation = 'visible' and exists (select 1 from public.books b where b.id = book_id and b.status = 'published'));
create policy "reviews: admin" on public.book_reviews for all using (public.is_admin()) with check (public.is_admin());

-- ===== 20261021000015_verification_community_samples.sql =====
-- Author verification, community for everyone (readers too), two-level replies, post bookmarks,
-- more in-app notifications, reader profiles, sample approval and author responses to reviews.
-- Additive: existing accounts, books, posts and permissions are kept. Existing authors are NOT marked
-- verified automatically; admins review them from Admin → Authors.

-- ---------------------------------------------------------------------------
-- 1. Author verification
-- ---------------------------------------------------------------------------
alter table public.profiles
  add column verified_author_at timestamptz,             -- set only by an admin decision
  add column verified_author_by uuid references public.profiles (id) on delete set null,
  add column notify_followers boolean not null default true,
  add column notify_replies boolean not null default true;

create table public.author_applications (
  id            uuid primary key default gen_random_uuid(),
  user_id       uuid not null references public.profiles (id) on delete cascade,
  pen_name      text not null check (char_length(pen_name) between 2 and 80),
  bio           text not null check (char_length(bio) between 20 and 600),
  language      text not null check (language in ('en', 'hi', 'both')),
  evidence      text not null check (char_length(evidence) between 10 and 2000),   -- book links, ISBNs, manuscript ownership notes
  status        text not null default 'pending' check (status in ('pending', 'approved', 'changes_requested', 'rejected', 'revoked')),
  decision_note text check (char_length(decision_note) <= 1000),
  reviewed_by   uuid references public.profiles (id) on delete set null,
  reviewed_at   timestamptz,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now()
);
create index author_applications_status_idx on public.author_applications (status, created_at);
create unique index author_applications_open_idx on public.author_applications (user_id) where status in ('pending', 'changes_requested');
create trigger author_applications_touch before update on public.author_applications for each row execute function public.touch_updated_at();
alter table public.author_applications enable row level security;
create policy "applications: own" on public.author_applications for select using (user_id = auth.uid());
create policy "applications: admin" on public.author_applications for all using (public.is_admin()) with check (public.is_admin());

-- Every status change is kept (who, when, what)
create table public.author_verification_events (
  id          bigserial primary key,
  user_id     uuid not null references public.profiles (id) on delete cascade,
  application_id uuid references public.author_applications (id) on delete set null,
  status      text not null,
  note        text,
  actor_id    uuid references public.profiles (id) on delete set null,
  created_at  timestamptz not null default now()
);
create index author_verification_events_user_idx on public.author_verification_events (user_id, created_at desc);
alter table public.author_verification_events enable row level security;
create policy "verification events: own" on public.author_verification_events for select using (user_id = auth.uid());
create policy "verification events: admin" on public.author_verification_events for all using (public.is_admin()) with check (public.is_admin());

-- Only admins (or the server) can set or clear verification
create or replace function public.guard_profile_verification()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if (new.verified_author_at is distinct from old.verified_author_at or new.verified_author_by is distinct from old.verified_author_by)
     and auth.uid() is not null and not public.is_admin() then
    raise exception 'Only an admin can change author verification';
  end if;
  return new;
end $$;
create trigger profiles_guard_verification before update of verified_author_at, verified_author_by on public.profiles
  for each row execute function public.guard_profile_verification();

-- ---------------------------------------------------------------------------
-- 2. Public profiles for everyone who takes part (readers too)
-- ---------------------------------------------------------------------------
create or replace function public.profile_default_handle()
returns trigger language plpgsql set search_path = public as $$
begin
  if new.handle is null and coalesce(trim(new.full_name), '') <> '' then
    new.handle := left(coalesce(nullif(trim(both '-' from lower(regexp_replace(new.full_name, '[^a-zA-Z0-9]+', '-', 'g'))), ''), 'member'), 30)
                  || '-' || substr(md5(new.id::text || clock_timestamp()::text), 1, 6);
  end if;
  return new;
end $$;

update public.profiles
   set handle = left(coalesce(nullif(trim(both '-' from lower(regexp_replace(full_name, '[^a-zA-Z0-9]+', '-', 'g'))), ''), 'member'), 30)
                || '-' || substr(md5(id::text || clock_timestamp()::text), 1, 6)
 where handle is null and coalesce(trim(full_name), '') <> '';

-- Name, handle, bio, photo and verification only: never phone, address or orders
create view public.public_profiles with (security_invoker = false) as
  select id, handle, full_name, bio, avatar_path, role in ('author', 'admin') as is_author, verified_author_at is not null as verified_author
    from public.profiles where handle is not null;
grant select on public.public_profiles to anon, authenticated;

-- ---------------------------------------------------------------------------
-- 3. Community for everyone: longer posts, replies to comments, private bookmarks
-- ---------------------------------------------------------------------------
alter table public.posts drop constraint posts_body_check;
alter table public.posts add constraint posts_body_check check (char_length(body) <= 3000);

alter table public.post_comments add column parent_id uuid references public.post_comments (id) on delete cascade;
alter table public.post_comments drop constraint post_comments_body_check;
alter table public.post_comments add constraint post_comments_body_check check (char_length(body) between 1 and 2000);
create index post_comments_parent_idx on public.post_comments (parent_id, created_at);

-- Two levels only: a reply must answer a top-level comment on the same post
create or replace function public.check_comment_depth()
returns trigger language plpgsql set search_path = public as $$
declare p public.post_comments;
begin
  if new.parent_id is null then return new; end if;
  select * into p from public.post_comments where id = new.parent_id;
  if not found or p.post_id <> new.post_id or p.parent_id is not null then
    raise exception 'Replies can only answer a top-level comment on the same post';
  end if;
  return new;
end $$;
create trigger post_comments_depth before insert or update of parent_id on public.post_comments
  for each row execute function public.check_comment_depth();

create table public.post_bookmarks (
  post_id    uuid not null references public.posts (id) on delete cascade,
  user_id    uuid not null references public.profiles (id) on delete cascade,
  created_at timestamptz not null default now(),
  primary key (post_id, user_id)
);
alter table public.post_bookmarks enable row level security;
create policy "post bookmarks: own" on public.post_bookmarks for select using (user_id = auth.uid());

-- ---------------------------------------------------------------------------
-- 4. Notifications: new follower, replies, verification decisions
-- ---------------------------------------------------------------------------
alter table public.notifications drop constraint notifications_kind_check;
alter table public.notifications add constraint notifications_kind_check
  check (kind in ('new_article', 'new_post', 'new_follower', 'reply', 'verification'));
alter table public.notifications add column ref_id uuid;   -- the follower, comment or application the notification is about
-- Not partial, so upserts can target it; rows without ref_id never clash (nulls are distinct)
create unique index notifications_ref_once_idx on public.notifications (user_id, kind, ref_id);

-- ---------------------------------------------------------------------------
-- 5. Samples: drafted privately, approved by the author, then published
-- ---------------------------------------------------------------------------
alter table public.books
  add column sample_draft_path      text check (char_length(sample_draft_path) <= 300),   -- private (manuscripts bucket) until approved
  add column sample_draft_from      integer,
  add column sample_draft_to        integer,
  add column sample_draft_source    text check (sample_draft_source in ('pages', 'upload')),
  add column sample_source          text check (sample_source in ('pages', 'upload')),
  add column sample_manuscript_version integer,       -- manuscript version the approved sample was made from
  add column sample_approved_at     timestamptz;

-- Uploaded samples have no page range
alter table public.books drop constraint books_sample_range;
alter table public.books add constraint books_sample_range check (
  sample_path is null
  or sample_from is null
  or (sample_to >= sample_from and sample_to - sample_from < 30)
);
update public.books set sample_source = 'pages', sample_approved_at = coalesce(sample_approved_at, updated_at) where sample_path is not null and sample_source is null;

-- ---------------------------------------------------------------------------
-- 6. Reviews: any logged-in reader may review; authors may respond (never delete)
-- ---------------------------------------------------------------------------
alter table public.book_reviews
  add column author_response    text check (char_length(author_response) <= 1000),
  add column author_response_at timestamptz;

-- Whether a review is from a verified purchase is worked out from current order status every time it is shown,
-- so cancellations and refunds are reflected immediately.
create or replace function public.review_is_verified(p_book uuid, p_user uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from public.order_items oi join public.orders o on o.id = oi.order_id
     where oi.book_id = p_book and o.buyer_id = p_user and o.status = 'delivered' and oi.reversed_at is null
  )
$$;
revoke execute on function public.review_is_verified(uuid, uuid) from public, anon;
grant execute on function public.review_is_verified(uuid, uuid) to authenticated;

-- ===== 20261022000016_private_book_files.sql =====
-- Private file locations on books (manuscript, print cover, sample draft, approved file pins) are no longer
-- readable through the public API. The files were already in a private bucket; now their paths are hidden too.
-- Everything else on a book stays readable under the existing row rules. The app reads these four columns
-- on the server only, after checking the person is the book's author or an admin.
revoke select on public.books from anon, authenticated;
grant select (
  id, author_id, slug, title, subtitle, author_name, description, language, genre, isbn, page_count, trim_size,
  binding, interior, paper, cover_finish, mrp, print_cost, cover_path, status, review_note, reviewed_by,
  reviewed_at, submitted_at, published_at, created_at, updated_at, manuscript_width_in, manuscript_height_in,
  print_cover_width_in, print_cover_height_in, sample_path, sample_from, sample_to, approved_files_at,
  files_confirmed_at, sample_draft_from, sample_draft_to, sample_draft_source, sample_source,
  sample_manuscript_version, sample_approved_at
) on public.books to anon, authenticated;

-- ===== 20261023000017_edition_ids.sql =====
-- Eliphas Edition IDs (EEID), e.g. EEID-2026-000123: our own permanent identifier for each approved book
-- edition/format, with a public page at /e/{EEID}. Not an ISBN (kept separate in books.isbn), not a copyright
-- registration and not proof that a physical copy is genuine. Each books row is one edition/format (its own
-- binding and language), so the ID lives on books. Additive: existing books get no EEID until an admin runs
-- the backfill from Admin → Edition IDs.

-- ---------------------------------------------------------------------------
-- 1. Editions: grouping, label, EEID, revised-file review, legal removal
-- ---------------------------------------------------------------------------
alter table public.books
  add column work_id               uuid not null default gen_random_uuid(),  -- editions of the same work share this
  add column edition_label         text check (char_length(edition_label) <= 60),  -- e.g. "Second edition"
  add column eeid                  text unique check (eeid ~ '^EEID-[0-9]{4}-[0-9]{6,}$'),
  add column eeid_assigned_at      timestamptz,
  add column eeid_assigned_by      uuid references public.profiles (id) on delete set null,
  add column print_review_requested_at timestamptz,  -- revised print files uploaded while live, not yet approved
  add column removed_at            timestamptz,      -- taken down by our team (e.g. legal); never shown publicly
  add column removed_reason        text check (char_length(removed_reason) <= 500);
create index books_work_idx on public.books (work_id);

-- Every EEID ever issued, kept even if its book is later removed, so an ID is never reused or reassigned
create table public.edition_ids (
  eeid         text primary key check (eeid ~ '^EEID-[0-9]{4}-[0-9]{6,}$'),
  book_id      uuid unique references public.books (id) on delete set null,
  assigned_at  timestamptz not null default now(),
  assigned_by  uuid references public.profiles (id) on delete set null,
  assigned_via text not null check (assigned_via in ('approval', 'backfill'))
);
alter table public.edition_ids enable row level security;
create policy "edition ids: admin reads" on public.edition_ids for select using (public.is_admin());
-- (writes only through assign_eeid below)

-- Numbers come from a sequence: never count + 1, never reused; gaps are fine
create sequence public.eeid_seq as bigint start 1 no cycle;

-- ---------------------------------------------------------------------------
-- 2. Assignment: server-only, transactional and idempotent
-- ---------------------------------------------------------------------------
-- Locks the book row, so concurrent approvals, retries and double clicks all get the same EEID.
-- The year is the year of assignment in India (Asia/Kolkata). Six digits minimum; grows beyond that.
create or replace function public.assign_eeid(p_book uuid, p_admin uuid, p_via text default 'approval')
returns text language plpgsql security definer set search_path = public as $$
declare
  b public.books;
  n bigint;
  new_eeid text;
begin
  if p_via not in ('approval', 'backfill') then raise exception 'Unknown assignment route'; end if;
  select * into b from public.books where books.id = p_book for update;
  if not found then raise exception 'Book not found'; end if;
  if b.eeid is not null then return b.eeid; end if;
  if b.status = 'draft' then raise exception 'Drafts do not get an Edition ID'; end if;
  if b.removed_at is not null then raise exception 'Removed editions do not get an Edition ID'; end if;
  n := nextval('public.eeid_seq');
  new_eeid := 'EEID-' || to_char(now() at time zone 'Asia/Kolkata', 'YYYY') || '-' ||
        case when n >= 1000000 then n::text else lpad(n::text, 6, '0') end;
  perform set_config('eliphas.assigning_eeid', 'on', true);
  update public.books set eeid = new_eeid, eeid_assigned_at = now(), eeid_assigned_by = p_admin where books.id = p_book;
  perform set_config('eliphas.assigning_eeid', 'off', true);
  insert into public.edition_ids (eeid, book_id, assigned_by, assigned_via) values (new_eeid, p_book, p_admin, p_via);
  insert into public.audit_log (actor_id, action, entity, entity_id, details)
    values (p_admin, 'edition.eeid_assigned', 'book', p_book::text, jsonb_build_object('eeid', new_eeid, 'via', p_via));
  return new_eeid;
end $$;
revoke execute on function public.assign_eeid(uuid, uuid, text) from public, anon, authenticated;
grant execute on function public.assign_eeid(uuid, uuid, text) to service_role;

-- EEIDs are immutable: set once by assign_eeid, never changed or cleared, by anyone (admins included)
create or replace function public.guard_eeid()
returns trigger language plpgsql set search_path = public as $$
begin
  if tg_op = 'INSERT' then
    if new.eeid is not null or new.eeid_assigned_at is not null or new.eeid_assigned_by is not null then
      raise exception 'Edition IDs are assigned on approval only';
    end if;
    return new;
  end if;
  if old.eeid is not null then
    if new.eeid is distinct from old.eeid or new.eeid_assigned_at is distinct from old.eeid_assigned_at
       or new.eeid_assigned_by is distinct from old.eeid_assigned_by then
      raise exception 'Edition IDs cannot be changed';
    end if;
  elsif (new.eeid is not null or new.eeid_assigned_at is not null or new.eeid_assigned_by is not null)
        and coalesce(current_setting('eliphas.assigning_eeid', true), 'off') <> 'on' then
    raise exception 'Edition IDs are assigned on approval only';
  end if;
  return new;
end $$;
create trigger books_guard_eeid before insert or update on public.books
  for each row execute function public.guard_eeid();

-- Editions with an EEID are never deleted (the ID stays reserved either way, in edition_ids)
create or replace function public.guard_book_delete()
returns trigger language plpgsql set search_path = public as $$
begin
  if old.eeid is not null then raise exception 'Books with an Edition ID cannot be deleted; unpublish or remove them instead'; end if;
  return old;
end $$;
create trigger books_guard_delete before delete on public.books
  for each row execute function public.guard_book_delete();

-- A removed edition can't go live again until our team restores it
create or replace function public.guard_removed_edition()
returns trigger language plpgsql set search_path = public as $$
begin
  if new.removed_at is not null and new.status = 'published' then
    raise exception 'This edition was removed by our team and cannot be published';
  end if;
  if (new.removed_at is distinct from old.removed_at or new.removed_reason is distinct from old.removed_reason)
     and auth.uid() is not null and not public.is_admin() then
    raise exception 'Only our team can remove or restore an edition';
  end if;
  return new;
end $$;
create trigger books_guard_removed before update on public.books
  for each row execute function public.guard_removed_edition();

-- ---------------------------------------------------------------------------
-- 3. Column access (books uses column-level grants since migration 000016)
-- ---------------------------------------------------------------------------
-- Public: the edition's ID, label and grouping. Not public: who assigned it, removal details, review flags.
grant select (work_id, edition_label, eeid, eeid_assigned_at) on public.books to anon, authenticated;

-- ---------------------------------------------------------------------------
-- 4. Revised print cover for a live book (e.g. to add the EEID/QR label)
-- ---------------------------------------------------------------------------
-- The author may add a new print-cover version to a live book. It is stored as a new file (the approved one is
-- kept), flagged for print review, and orders keep printing the approved version until our team approves it.
create or replace function public.can_add_live_print_cover(object_name text)
returns boolean language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from public.books b
    where b.id::text = (storage.foldername(object_name))[2]
      and b.author_id = auth.uid()
      and (storage.foldername(object_name))[1] = auth.uid()::text
      and b.status = 'published'
      and b.removed_at is null
      and storage.filename(object_name) ~ '^print-cover-[0-9a-f-]{36}\.pdf$'
  )
$$;
create policy "manuscripts: author adds revised print cover to live book" on storage.objects
  for insert to authenticated with check (bucket_id = 'manuscripts' and public.can_add_live_print_cover(name));
-- Uploads use "upsert", which also checks the update rule (each version has a new unique name)
create policy "manuscripts: author upserts revised print cover to live book" on storage.objects
  for update to authenticated using (bucket_id = 'manuscripts' and public.can_add_live_print_cover(name));

-- ===== 20261024000018_fix_admin_finance.sql =====
-- Fix: admin_finance failed with "cannot cast type record to order_items" whenever there were paid orders,
-- because the lines CTE carried an extra order_status column that made each row not castable to order_items.
-- The column was never used; removing it restores the Finance page. Figures and permissions are unchanged.
create or replace function public.admin_finance(p_from timestamptz, p_to timestamptz)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  result jsonb;
begin
  if not public.is_admin() then raise exception 'ADMIN_ONLY'; end if;
  with lines as (
    select oi.*
    from public.order_items oi join public.orders o on o.id = oi.order_id
    where o.paid_at >= p_from and o.paid_at < p_to and public.is_earning_status(o.status) and oi.reversed_at is null
  ), ord as (
    select * from public.orders o
    where o.paid_at >= p_from and o.paid_at < p_to and o.status <> 'pending_payment'
  )
  select jsonb_build_object(
    'book_sales_value', coalesce((select sum(unit_price * quantity) from lines), 0),
    'print_costs',      coalesce((select sum(coalesce(print_cost_total, print_cost * quantity)) from lines), 0),
    'commission',       coalesce((select sum(coalesce(commission, platform_fee * quantity)) from lines), 0),
    'commission_gst',   coalesce((select sum(coalesce(commission_gst, 0)) from lines), 0),
    'gateway_costs',    coalesce((select sum(coalesce(gateway_allocated, payment_fee * quantity)) from lines), 0),
    'author_earnings',  coalesce((select sum(public.line_earning(l::public.order_items)) from lines l), 0),
    'shipping_collected', coalesce((select sum(shipping) from ord where public.is_earning_status(status)), 0),
    'shipping_promotions', coalesce((select sum(shipping_discount) from ord where public.is_earning_status(status)), 0),
    'book_refunds',     coalesce((select sum(refund_amount) from ord where refund_status in ('processed', 'pending')), 0),
    'service_revenue',  coalesce((select sum(base_paise) from public.payments where purpose = 'service' and status in ('paid', 'partially_refunded') and paid_at >= p_from and paid_at < p_to), 0) / 100.0,
    'service_gst',      coalesce((select sum(gst_paise) from public.payments where purpose = 'service' and status in ('paid', 'partially_refunded') and paid_at >= p_from and paid_at < p_to), 0) / 100.0,
    'subscription_revenue', coalesce((select sum(base_paise) from public.payments where purpose = 'subscription' and status in ('paid', 'partially_refunded') and paid_at >= p_from and paid_at < p_to), 0) / 100.0,
    'subscription_gst', coalesce((select sum(gst_paise) from public.payments where purpose = 'subscription' and status in ('paid', 'partially_refunded') and paid_at >= p_from and paid_at < p_to), 0) / 100.0,
    'other_refunds',    coalesce((select sum(refunded_paise) from public.payments where refunded_at >= p_from and refunded_at < p_to), 0) / 100.0,
    'author_liability', coalesce((select sum(greatest(balance, 0)) from public.author_balances), 0)
  ) into result;
  return result;
end $$;

-- ===== 20261025000019_distribution_requests.sql =====
-- Distribution requests: an author asks Eliphas to review one of their published books for
-- Amazon India, Flipkart or international distribution. Intake and review only: nothing is
-- submitted to a retailer, nothing is charged, and existing royalties are unchanged.

create table public.distribution_requests (
  id                uuid primary key default gen_random_uuid(),
  author_id         uuid not null references public.profiles (id) on delete cascade,
  book_id           uuid not null references public.books (id) on delete cascade,
  channel           text not null check (channel in ('amazon_india', 'flipkart', 'international')),
  markets           text not null check (length(btrim(markets)) between 2 and 200),
  residence_country text not null check (length(btrim(residence_country)) between 2 and 80),
  rights_confirmed  boolean not null check (rights_confirmed),
  status            text not null default 'requested'
                    check (status in ('requested', 'reviewing', 'needs_information', 'declined')),
  review_note       text not null default '' check (length(review_note) <= 2000),
  reviewed_by       uuid references public.profiles (id) on delete set null,
  reviewed_at       timestamptz,
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now(),
  unique (book_id, channel)
);
create index distribution_requests_queue on public.distribution_requests (created_at desc);
create index distribution_requests_author on public.distribution_requests (author_id, created_at desc);

-- The database stamps every review: who, when, and a fresh updated_at (used to reject stale edits)
create function public.stamp_distribution_review()
returns trigger language plpgsql as $$
begin
  -- clock_timestamp(), not now(): two saves in one transaction still get different values
  new.updated_at = clock_timestamp();
  new.reviewed_at = new.updated_at;
  new.reviewed_by = auth.uid();
  return new;
end $$;
create trigger distribution_requests_review before update on public.distribution_requests
  for each row execute function public.stamp_distribution_review();

-- The author's own live book. Security definer because removed_at isn't readable by authors (column grants).
create function public.can_request_distribution(target uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from public.books b
    where b.id = target and b.author_id = auth.uid() and b.status = 'published' and b.removed_at is null
  )
$$;

alter table public.distribution_requests enable row level security;
revoke all on public.distribution_requests from anon, authenticated;
grant select on public.distribution_requests to authenticated;
-- Authors can only fill in the request itself; status, notes and timestamps take their defaults
grant insert (author_id, book_id, channel, markets, residence_country, rights_confirmed)
  on public.distribution_requests to authenticated;
grant update (status, review_note) on public.distribution_requests to authenticated;

create policy "distribution: author or admin reads" on public.distribution_requests
  for select to authenticated using (author_id = auth.uid() or public.is_admin());
create policy "distribution: author requests own published book" on public.distribution_requests
  for insert to authenticated with check (
    author_id = auth.uid()
    and status = 'requested' and review_note = ''
    and public.my_role() in ('author', 'admin')
    and public.can_request_distribution(book_id)
  );
create policy "distribution: admin reviews" on public.distribution_requests
  for update to authenticated using (public.is_admin()) with check (public.is_admin());

-- ===== 20261026000020_distribution_replies.sql =====
-- Distribution requests, part 2: the author is notified of each review and can reply to "Needs information".
-- Still intake only: nothing is submitted to a retailer or charged.

-- 1. In-app notification when our team reviews a request
alter table public.notifications drop constraint notifications_kind_check;
alter table public.notifications add constraint notifications_kind_check
  check (kind in ('new_article', 'new_post', 'new_follower', 'reply', 'verification', 'distribution'));

-- 2. The author's latest reply
alter table public.distribution_requests
  add column author_reply      text not null default '' check (length(author_reply) <= 2000),
  add column author_replied_at timestamptz;

-- Only an admin's save counts as a review; every save still gets a fresh updated_at (stale-edit protection)
create or replace function public.stamp_distribution_review()
returns trigger language plpgsql as $$
begin
  -- clock_timestamp(), not now(): two saves in one transaction still get different values
  new.updated_at = clock_timestamp();
  if public.is_admin() then
    new.reviewed_at = new.updated_at;
    new.reviewed_by = auth.uid();
  end if;
  return new;
end $$;

-- 3. Reply to "Needs information": own request only, only in that status, and only if nobody changed it meanwhile.
-- The request goes back to "requested" so it appears in the team's open queue. Returns false if nothing matched.
create function public.reply_to_distribution_review(
  p_id uuid, p_previous timestamptz, p_reply text, p_markets text, p_residence text
) returns boolean language plpgsql security definer set search_path = public as $$
declare
  found_id uuid;
begin
  if length(btrim(coalesce(p_reply, ''))) not between 5 and 2000
     or length(btrim(coalesce(p_markets, ''))) not between 2 and 200
     or length(btrim(coalesce(p_residence, ''))) not between 2 and 80 then
    raise exception 'Invalid reply';
  end if;
  update public.distribution_requests
     set author_reply = btrim(p_reply),
         author_replied_at = clock_timestamp(),
         markets = btrim(p_markets),
         residence_country = btrim(p_residence),
         status = 'requested'
   where id = p_id
     and author_id = auth.uid()
     and status = 'needs_information'
     and updated_at = p_previous
  returning id into found_id;
  return found_id is not null;
end $$;
revoke execute on function public.reply_to_distribution_review(uuid, timestamptz, text, text, text) from public, anon;
grant execute on function public.reply_to_distribution_review(uuid, timestamptz, text, text, text) to authenticated;

-- ===== 20261027000021_refund_ledger.sql =====
-- Refund ledger for Pro and service payments, and safer book-order refunds.
-- Before: a payment was marked "refunded" as soon as Razorpay accepted the request, even if the refund later failed,
-- and two quick clicks could start two refunds. Now every refund is a row: the amount is reserved atomically before
-- Razorpay is called, and the payment's refunded total changes only when Razorpay confirms the refund.

create table public.payment_refunds (
  id                 uuid primary key default gen_random_uuid(),
  payment_id         uuid not null references public.payments (id),
  amount_paise       integer not null check (amount_paise > 0),
  status             text not null default 'requested' check (status in ('requested', 'pending', 'processed', 'failed')),
  razorpay_refund_id text unique,
  reason             text not null default '' check (length(reason) <= 500),
  error              text check (length(error) <= 1000),
  created_by         uuid references public.profiles (id) on delete set null,
  created_at         timestamptz not null default now(),
  updated_at         timestamptz not null default now(),
  processed_at       timestamptz
);
create index payment_refunds_payment_idx on public.payment_refunds (payment_id);
create index payment_refunds_open_idx on public.payment_refunds (status) where status <> 'processed';
create trigger payment_refunds_touch before update on public.payment_refunds
  for each row execute function public.touch_updated_at();

alter table public.payment_refunds enable row level security;
revoke all on public.payment_refunds from anon, authenticated;
grant select on public.payment_refunds to authenticated;
create policy "payment refunds: admin reads" on public.payment_refunds for select to authenticated using (public.is_admin());

-- Reserve a refund. Locks the payment so concurrent refunds can't exceed what was paid.
-- Failed attempts don't count. Pass p_retry to reopen a failed attempt instead of creating a new one.
create function public.begin_payment_refund(p_payment uuid, p_amount integer, p_reason text, p_actor uuid, p_retry uuid default null)
returns uuid language plpgsql security definer set search_path = public as $$
declare
  pay public.payments;
  reserved integer;
  refund_row uuid;
begin
  select * into pay from public.payments where id = p_payment for update;
  if pay.id is null then raise exception 'Payment not found'; end if;
  if pay.status not in ('paid', 'partially_refunded', 'refunded') then raise exception 'Only paid payments can be refunded'; end if;
  -- Reserved = refunds made before this ledger existed (refunded_paise not explained by processed rows)
  --          + every attempt that hasn't failed
  select (pay.refunded_paise - coalesce(sum(amount_paise) filter (where status = 'processed'), 0))
         + coalesce(sum(amount_paise) filter (where status <> 'failed' and id is distinct from p_retry), 0)
    into reserved
    from public.payment_refunds where payment_id = p_payment;
  if p_amount is null or p_amount <= 0 or reserved + p_amount > pay.amount_paise then
    raise exception 'Refund exceeds the amount left (% paise)', pay.amount_paise - reserved;
  end if;
  if p_retry is not null then
    update public.payment_refunds set status = 'requested', error = null
     where id = p_retry and payment_id = p_payment and status = 'failed' and amount_paise = p_amount
    returning id into refund_row;
    if refund_row is null then raise exception 'Only a failed refund can be retried'; end if;
    return refund_row;
  end if;
  insert into public.payment_refunds (payment_id, amount_paise, reason, created_by)
  values (p_payment, p_amount, left(coalesce(p_reason, ''), 500), p_actor)
  returning id into refund_row;
  return refund_row;
end $$;

-- Record Razorpay's answer. The payment's refunded total moves only on the first change to "processed".
create function public.settle_payment_refund(p_refund uuid, p_status text, p_razorpay_id text default null, p_error text default null)
returns void language plpgsql security definer set search_path = public as $$
declare
  r public.payment_refunds;
begin
  if p_status not in ('pending', 'processed', 'failed') then raise exception 'Invalid refund status'; end if;
  select * into r from public.payment_refunds where id = p_refund for update;
  if r.id is null then raise exception 'Refund not found'; end if;
  if r.status = 'processed' then return; end if;  -- already final; later events change nothing
  update public.payment_refunds
     set status = p_status,
         razorpay_refund_id = coalesce(p_razorpay_id, razorpay_refund_id),
         error = case when p_status = 'failed' then left(p_error, 1000) else null end,
         processed_at = case when p_status = 'processed' then now() else null end
   where id = r.id;
  if p_status = 'processed' then
    update public.payments
       set refunded_paise = refunded_paise + r.amount_paise,
           status = case when refunded_paise + r.amount_paise >= amount_paise then 'refunded' else 'partially_refunded' end,
           refund_id = coalesce(p_razorpay_id, r.razorpay_refund_id, refund_id),
           refunded_at = now()
     where id = r.payment_id;
  end if;
end $$;

revoke execute on function public.begin_payment_refund(uuid, integer, text, uuid, uuid) from public, anon, authenticated;
revoke execute on function public.settle_payment_refund(uuid, text, text, text) from public, anon, authenticated;
grant execute on function public.begin_payment_refund(uuid, integer, text, uuid, uuid) to service_role;
grant execute on function public.settle_payment_refund(uuid, text, text, text) to service_role;

-- Book orders: claim the refund before calling Razorpay, so two clicks (or a click and a retry) can't refund twice.
-- 'requested' = claimed, Razorpay not answered yet.
alter table public.orders drop constraint if exists orders_refund_status_check;
alter table public.orders add constraint orders_refund_status_check check (refund_status in ('requested', 'pending', 'processed', 'failed'));

-- ===== 20261028000022_operations.sql =====
-- Operations before launch: parcel tracking links, order update emails (with a delivery log),
-- the contact form inbox and author payout runs. Nothing here sends anything by itself.

-- ---------------------------------------------------------------------------
-- 1. Tracking link the printer pastes from the courier's receipt (optional)
-- ---------------------------------------------------------------------------
alter table public.orders
  add column tracking_url text check (tracking_url is null or (tracking_url like 'https://%' and length(tracking_url) <= 500));

-- ---------------------------------------------------------------------------
-- 2. Order update emails
-- ---------------------------------------------------------------------------
-- Optional email for order updates. Login stays by phone (or Google).
alter table public.profiles
  add column email text check (email is null or (length(email) <= 254 and email ~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$')),
  add column notify_order_emails boolean not null default true;
-- The address an order's updates go to, as entered at checkout
alter table public.orders
  add column contact_email text check (contact_email is null or (length(contact_email) <= 254 and contact_email ~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$'));

-- Every email the app tries to send. dedupe_key makes each update send once (e.g. "order:<id>:shipped").
create table public.email_outbox (
  id           uuid primary key default gen_random_uuid(),
  kind         text not null check (kind in ('order_confirmed', 'order_shipped', 'order_delivered', 'order_cancelled', 'refund_processed', 'contact_message')),
  to_email     text not null check (length(to_email) <= 254),
  subject      text not null check (length(subject) <= 200),
  html         text not null,
  text_body    text not null,
  dedupe_key   text unique,
  status       text not null default 'queued' check (status in ('queued', 'sent', 'failed', 'skipped')),
  attempts     integer not null default 0,
  last_error   text check (length(last_error) <= 1000),
  provider_id  text,
  user_id      uuid references public.profiles (id) on delete set null,
  order_id     uuid references public.orders (id) on delete set null,
  created_at   timestamptz not null default now(),
  sent_at      timestamptz
);
create index email_outbox_retry_idx on public.email_outbox (status, created_at) where status in ('queued', 'failed');
create index email_outbox_recent_idx on public.email_outbox (created_at desc);
alter table public.email_outbox enable row level security;
revoke all on public.email_outbox from anon, authenticated;
grant select on public.email_outbox to authenticated;
create policy "email outbox: admin reads" on public.email_outbox for select to authenticated using (public.is_admin());

-- ---------------------------------------------------------------------------
-- 3. Contact form inbox (guests and members). Written by the server only.
-- ---------------------------------------------------------------------------
create table public.contact_messages (
  id           uuid primary key default gen_random_uuid(),
  name         text not null check (length(btrim(name)) between 2 and 80),
  email        text not null check (length(email) <= 254 and email ~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$'),
  phone        text check (length(phone) <= 20),
  topic        text not null check (topic in ('order', 'publishing', 'payout', 'services', 'other')),
  order_number text check (length(order_number) <= 40),
  message      text not null check (length(btrim(message)) between 10 and 4000),
  user_id      uuid references public.profiles (id) on delete set null,
  ip_hash      text,                         -- salted hash, only for rate limiting
  status       text not null default 'new' check (status in ('new', 'replied', 'closed')),
  admin_note   text check (length(admin_note) <= 2000),
  handled_by   uuid references public.profiles (id) on delete set null,
  handled_at   timestamptz,
  created_at   timestamptz not null default now()
);
create index contact_messages_inbox_idx on public.contact_messages (status, created_at desc);
create index contact_messages_rate_idx on public.contact_messages (ip_hash, created_at);
alter table public.contact_messages enable row level security;
revoke all on public.contact_messages from anon, authenticated;
grant select on public.contact_messages to authenticated;
create policy "contact messages: admin reads" on public.contact_messages for select to authenticated using (public.is_admin());

-- ---------------------------------------------------------------------------
-- 4. Author payout runs: everyone owed, in one batch, paid by bank/UPI and marked paid with the UTR
-- ---------------------------------------------------------------------------
create table public.payout_runs (
  id           uuid primary key default gen_random_uuid(),
  status       text not null default 'open' check (status in ('open', 'completed', 'cancelled')),
  minimum      numeric(10, 2) not null default 0 check (minimum >= 0),
  total        numeric(12, 2) not null default 0,
  authors      integer not null default 0,
  created_by   uuid references public.profiles (id) on delete set null,
  created_at   timestamptz not null default now(),
  closed_at    timestamptz
);
create unique index payout_runs_one_open on public.payout_runs ((true)) where status = 'open';
alter table public.payout_runs enable row level security;
create policy "payout runs: admin" on public.payout_runs for all using (public.is_admin()) with check (public.is_admin());

alter table public.payouts
  add column run_id uuid references public.payout_runs (id),
  add column upi text;  -- the UPI ID used for this payout, as it was when the run started

-- What an author can be paid now: earnings on delivered orders, minus paid and still-pending payouts
create function public.payable_now(p_author uuid) returns numeric
language sql stable security definer set search_path = public as $$
  select greatest(0,
    coalesce((select sum(public.line_earning(oi)) from public.order_items oi join public.orders o on o.id = oi.order_id
              where oi.author_id = p_author and o.status = 'delivered'), 0)
    - coalesce((select sum(amount) from public.payouts where author_id = p_author and status in ('paid', 'pending')), 0)
  )::numeric(12, 2)
$$;

-- Start a run: one pending payout per author owed at least p_minimum who has a UPI ID. One open run at a time.
create function public.create_payout_run(p_minimum numeric, p_actor uuid) returns uuid
language plpgsql security definer set search_path = public as $$
declare
  run_id uuid;
begin
  if p_minimum is null or p_minimum < 0 then raise exception 'Invalid minimum'; end if;
  perform pg_advisory_xact_lock(hashtext('eliphas.payout_run'));
  if exists (select 1 from public.payout_runs where status = 'open') then
    raise exception 'Finish or cancel the open payout run first';
  end if;
  insert into public.payout_runs (minimum, created_by) values (p_minimum, p_actor) returning id into run_id;
  insert into public.payouts (author_id, amount, status, run_id, upi, created_by, note)
  select p.id, public.payable_now(p.id), 'pending', run_id, p.payout_upi, p_actor, 'Payout run'
    from public.profiles p
   where p.payout_upi is not null and btrim(p.payout_upi) <> ''
     and public.payable_now(p.id) >= greatest(p_minimum, 0.01);
  update public.payout_runs r
     set total = coalesce((select sum(amount) from public.payouts where payouts.run_id = r.id), 0),
         authors = (select count(*) from public.payouts where payouts.run_id = r.id)
   where r.id = run_id;
  return run_id;
end $$;

-- Mark one payout in an open run paid (with the bank/UPI reference) or cancelled. Closes the run when nothing is pending.
create function public.settle_run_payout(p_payout uuid, p_paid boolean, p_reference text) returns void
language plpgsql security definer set search_path = public as $$
declare
  pay public.payouts;
begin
  select * into pay from public.payouts where id = p_payout for update;
  if pay.id is null or pay.run_id is null or pay.status <> 'pending' then raise exception 'This payout is not waiting in a run'; end if;
  if p_paid and length(btrim(coalesce(p_reference, ''))) < 4 then raise exception 'Enter the payment reference (UTR)'; end if;
  update public.payouts
     set status = case when p_paid then 'paid'::public.payout_status else 'cancelled'::public.payout_status end,
         reference = case when p_paid then btrim(p_reference) else reference end,
         paid_at = case when p_paid then now() else null end
   where id = p_payout;
  if not exists (select 1 from public.payouts where run_id = pay.run_id and status = 'pending') then
    update public.payout_runs set status = 'completed', closed_at = now() where id = pay.run_id and status = 'open';
  end if;
end $$;

-- Cancel an open run: its pending payouts are released (already-paid ones stay paid)
create function public.cancel_payout_run(p_run uuid) returns void
language plpgsql security definer set search_path = public as $$
begin
  update public.payouts set status = 'cancelled' where run_id = p_run and status = 'pending';
  update public.payout_runs set status = 'cancelled', closed_at = now() where id = p_run and status = 'open';
end $$;

revoke execute on function public.payable_now(uuid) from public, anon, authenticated;
revoke execute on function public.create_payout_run(numeric, uuid) from public, anon, authenticated;
revoke execute on function public.settle_run_payout(uuid, boolean, text) from public, anon, authenticated;
revoke execute on function public.cancel_payout_run(uuid) from public, anon, authenticated;
grant execute on function public.payable_now(uuid) to service_role;
grant execute on function public.create_payout_run(numeric, uuid) to service_role;
grant execute on function public.settle_run_payout(uuid, boolean, text) to service_role;
grant execute on function public.cancel_payout_run(uuid) to service_role;

-- ===== 20261029000023_referrals.sql =====
-- Referral programme: invite links, a first-order discount for the invited friend, and account credit for the
-- person who invited them. Credit is spent as a discount on book orders and is paid for by the platform
-- (order_items.platform_discount), so authors' royalties never change.
-- Everything starts switched off with zero amounts. An admin turns it on and sets the amounts in Admin → Referrals.

-- ---------------------------------------------------------------------------
-- 1. Settings (amounts in whole rupees)
-- ---------------------------------------------------------------------------
insert into public.settings (key, value, description) values (
  'referrals',
  jsonb_build_object(
    'enabled', false,                    -- master switch
    'reader_enabled', false,             -- a reader invites a friend
    'reader_friend_discount', 0,         -- off the friend's first order
    'reader_referrer_credit', 0,         -- credit for the reader who invited
    'author_enabled', false,             -- an author's link brings a new customer
    'author_buyer_discount', 0,
    'author_credit', 0,
    'author_author_enabled', false,      -- an invited person publishes their first book
    'author_author_credit', 0,           -- for each of the two
    'min_order', 0,                      -- books value needed for the first-order discount and reward
    'monthly_cap', 0,                    -- most credit one person can earn in a month (0 = no limit)
    'credit_expiry_days', 180,
    'reward_wait_days', 7,               -- days after delivery before the reward is given
    'max_credit_percent', 50             -- most of an order's books value that credit can pay
  ),
  'Referral programme. Off by default; amounts in rupees. Edited in Admin → Referrals.'
) on conflict (key) do nothing;

-- ---------------------------------------------------------------------------
-- 2. Invite codes, who invited whom, rewards
-- ---------------------------------------------------------------------------
create table public.referral_codes (
  user_id    uuid primary key references public.profiles (id) on delete cascade,
  code       text not null unique check (code ~ '^[A-Z0-9]{6,10}$'),
  created_at timestamptz not null default now()
);
alter table public.referral_codes enable row level security;
create policy "referral codes: owner reads" on public.referral_codes for select to authenticated using (user_id = auth.uid() or public.is_admin());

-- One row per invited account, created when a new account finishes setting up after opening an invite link
create table public.referrals (
  id             uuid primary key default gen_random_uuid(),
  referrer_id    uuid references public.profiles (id) on delete set null,
  referred_id    uuid not null unique references public.profiles (id) on delete cascade,
  code           text not null,
  referrer_kind  text not null check (referrer_kind in ('reader', 'author')),  -- which programme, as it was at sign-up
  status         text not null default 'active' check (status in ('active', 'blocked')),
  blocked_reason text check (length(blocked_reason) <= 300),
  created_at     timestamptz not null default now(),
  check (referrer_id is null or referrer_id <> referred_id)
);
create index referrals_referrer_idx on public.referrals (referrer_id, created_at desc);
alter table public.referrals enable row level security;
create policy "referrals: people involved read" on public.referrals for select to authenticated
  using (referrer_id = auth.uid() or referred_id = auth.uid() or public.is_admin());

create table public.referral_rewards (
  id              uuid primary key default gen_random_uuid(),
  referral_id     uuid not null references public.referrals (id) on delete cascade,
  user_id         uuid not null references public.profiles (id) on delete cascade,  -- who gets the credit
  reason          text not null check (reason in ('friend_first_order', 'author_first_book')),
  order_id        uuid references public.orders (id) on delete set null,
  book_id         uuid references public.books (id) on delete set null,
  amount          numeric(10, 2) not null check (amount >= 0),
  status          text not null check (status in ('granted', 'cancelled')),
  note            text check (length(note) <= 300),  -- e.g. why it was cancelled
  created_at      timestamptz not null default now(),
  cancelled_at    timestamptz,
  unique (referral_id, user_id, reason)
);
create index referral_rewards_user_idx on public.referral_rewards (user_id, created_at desc);
create index referral_rewards_order_idx on public.referral_rewards (order_id);
alter table public.referral_rewards enable row level security;
create policy "referral rewards: owner reads" on public.referral_rewards for select to authenticated using (user_id = auth.uid() or public.is_admin());

-- ---------------------------------------------------------------------------
-- 3. Credit ledger: every change to someone's credit. Positive rows expire; spending uses the oldest credit first.
-- ---------------------------------------------------------------------------
create table public.credit_ledger (
  id         uuid primary key default gen_random_uuid(),
  user_id    uuid not null references public.profiles (id) on delete cascade,
  amount     numeric(10, 2) not null check (amount <> 0),
  kind       text not null check (kind in ('reward', 'spend', 'return', 'adjust', 'clawback')),
  expires_at timestamptz,  -- positive rows only
  order_id   uuid references public.orders (id) on delete set null,
  reward_id  uuid references public.referral_rewards (id) on delete set null,
  note       text check (length(note) <= 300),
  created_by uuid references public.profiles (id) on delete set null,
  created_at timestamptz not null default clock_timestamp(),
  check (case when amount > 0 then kind in ('reward', 'return', 'adjust') and expires_at is not null
              else kind in ('spend', 'clawback', 'adjust') and expires_at is null end)
);
create index credit_ledger_user_idx on public.credit_ledger (user_id, created_at);
-- Each order spends credit once and gets it back once; each reward is given and taken back once
create unique index credit_ledger_one_spend on public.credit_ledger (order_id) where kind = 'spend';
create unique index credit_ledger_one_return on public.credit_ledger (order_id) where kind = 'return';
create unique index credit_ledger_one_reward on public.credit_ledger (reward_id) where kind = 'reward';
create unique index credit_ledger_one_clawback on public.credit_ledger (reward_id) where kind = 'clawback';
alter table public.credit_ledger enable row level security;
create policy "credit ledger: owner reads" on public.credit_ledger for select to authenticated using (user_id = auth.uid() or public.is_admin());

-- What a book order took off the price, both paid for by the platform
alter table public.orders
  add column referral_discount numeric(10, 2) not null default 0 check (referral_discount >= 0),
  add column credit_used numeric(10, 2) not null default 0 check (credit_used >= 0),
  add column referral_id uuid references public.referrals (id) on delete set null;

-- ---------------------------------------------------------------------------
-- 4. Balance: replays the ledger in time order. A spend uses credit that hadn't expired at that moment,
--    soonest-expiring first. Anything taken back beyond the balance is owed and comes off later credit.
-- ---------------------------------------------------------------------------
create function public.credit_balance(p_user uuid, out balance numeric, out next_expiry timestamptz, out expiring numeric)
language plpgsql stable security definer set search_path = public as $$
declare
  e record;
  amounts numeric[] := '{}';
  expiries timestamptz[] := '{}';
  owed numeric := 0;
  need numeric;
  take numeric;
  pick int;
  i int;
begin
  for e in select amount, expires_at, created_at from public.credit_ledger where user_id = p_user order by created_at, id loop
    if e.amount > 0 then
      take := least(owed, e.amount);
      owed := owed - take;
      amounts := amounts || (e.amount - take);
      expiries := expiries || e.expires_at;
    else
      need := -e.amount;
      while need > 0 loop
        pick := null;
        for i in 1 .. coalesce(array_length(amounts, 1), 0) loop
          if amounts[i] > 0 and expiries[i] > e.created_at and (pick is null or expiries[i] < expiries[pick]) then pick := i; end if;
        end loop;
        exit when pick is null;
        take := least(need, amounts[pick]);
        amounts[pick] := amounts[pick] - take;
        need := need - take;
      end loop;
      owed := owed + need;
    end if;
  end loop;

  balance := 0;
  for i in 1 .. coalesce(array_length(amounts, 1), 0) loop
    if amounts[i] > 0 and expiries[i] > now() then
      balance := balance + amounts[i];
      if next_expiry is null or expiries[i] < next_expiry then next_expiry := expiries[i]; end if;
    end if;
  end loop;
  balance := round(balance - owed, 2);
  expiring := 0;
  if next_expiry is not null then
    for i in 1 .. coalesce(array_length(amounts, 1), 0) loop
      if amounts[i] > 0 and expiries[i] = next_expiry then expiring := expiring + amounts[i]; end if;
    end loop;
  end if;
end $$;

-- Spend credit on an order, under a per-person lock so two checkouts can't spend the same credit
create function public.spend_credit(p_user uuid, p_order uuid, p_amount numeric) returns void
language plpgsql security definer set search_path = public as $$
begin
  if p_amount is null or p_amount <= 0 then raise exception 'Invalid amount'; end if;
  perform pg_advisory_xact_lock(hashtext('eliphas.credit:' || p_user::text));
  if (select balance from public.credit_balance(p_user)) < p_amount then raise exception 'INSUFFICIENT_CREDIT'; end if;
  insert into public.credit_ledger (user_id, amount, kind, order_id, note) values (p_user, -p_amount, 'spend', p_order, 'Used on an order');
end $$;

-- Give a referral reward as credit, within the person's monthly limit (calendar month, India time).
-- Returns 'granted', 'capped' (limit reached: recorded as cancelled) or 'exists'.
create function public.grant_referral_reward(
  p_referral uuid, p_user uuid, p_reason text, p_amount numeric, p_cap numeric, p_expiry_days int, p_order uuid default null, p_book uuid default null
) returns text
language plpgsql security definer set search_path = public as $$
declare
  earned numeric;
  amount numeric := p_amount;
  reward_id uuid;
begin
  if p_amount is null or p_amount <= 0 or p_expiry_days is null or p_expiry_days < 1 then raise exception 'Invalid reward'; end if;
  perform pg_advisory_xact_lock(hashtext('eliphas.credit:' || p_user::text));
  if exists (select 1 from public.referral_rewards where referral_id = p_referral and user_id = p_user and reason = p_reason) then return 'exists'; end if;
  if coalesce(p_cap, 0) > 0 then
    select coalesce(sum(r.amount), 0) into earned from public.referral_rewards r
     where r.user_id = p_user and r.status = 'granted'
       and r.created_at >= (date_trunc('month', now() at time zone 'Asia/Kolkata') at time zone 'Asia/Kolkata');
    amount := least(p_amount, greatest(p_cap - earned, 0));
  end if;
  if amount <= 0 then
    insert into public.referral_rewards (referral_id, user_id, reason, order_id, book_id, amount, status, note, cancelled_at)
    values (p_referral, p_user, p_reason, p_order, p_book, 0, 'cancelled', 'Monthly limit reached', now());
    return 'capped';
  end if;
  insert into public.referral_rewards (referral_id, user_id, reason, order_id, book_id, amount, status)
  values (p_referral, p_user, p_reason, p_order, p_book, amount, 'granted') returning id into reward_id;
  insert into public.credit_ledger (user_id, amount, kind, expires_at, reward_id, order_id, note)
  values (p_user, amount, 'reward', now() + make_interval(days => p_expiry_days), reward_id, p_order,
          case p_reason when 'friend_first_order' then 'Invite reward' else 'Author invite reward' end);
  return 'granted';
end $$;

-- Take back a granted reward (admin, or automatically when its order is refunded)
create function public.cancel_referral_reward(p_reward uuid, p_actor uuid, p_note text) returns boolean
language plpgsql security definer set search_path = public as $$
declare
  r public.referral_rewards;
begin
  select * into r from public.referral_rewards where id = p_reward for update;
  if r.id is null or r.status <> 'granted' then return false; end if;
  update public.referral_rewards set status = 'cancelled', note = left(p_note, 300), cancelled_at = now() where id = p_reward;
  if r.amount > 0 then
    insert into public.credit_ledger (user_id, amount, kind, reward_id, note, created_by)
    values (r.user_id, -r.amount, 'clawback', r.id, left(coalesce(p_note, 'Reward cancelled'), 300), p_actor)
    on conflict do nothing;
  end if;
  return true;
end $$;

-- Admin correction: add credit (expires like any other) or remove it
create function public.adjust_credit(p_user uuid, p_amount numeric, p_note text, p_actor uuid, p_expiry_days int) returns void
language plpgsql security definer set search_path = public as $$
begin
  if p_amount is null or p_amount = 0 or abs(p_amount) > 100000 then raise exception 'Invalid amount'; end if;
  if length(btrim(coalesce(p_note, ''))) < 3 then raise exception 'Add a short note'; end if;
  perform pg_advisory_xact_lock(hashtext('eliphas.credit:' || p_user::text));
  insert into public.credit_ledger (user_id, amount, kind, expires_at, note, created_by)
  values (p_user, p_amount, 'adjust', case when p_amount > 0 then now() + make_interval(days => greatest(coalesce(p_expiry_days, 180), 1)) end,
          left(btrim(p_note), 300), p_actor);
end $$;

-- When an order is cancelled or refunded: its credit comes back, and any reward it earned is taken back.
-- A trigger, so every path (buyer, admin, unpaid checkout, problem refund) is covered.
create function public.orders_credit_on_cancel() returns trigger
language plpgsql security definer set search_path = public as $$
declare
  days int;
  r record;
begin
  if (new.status = 'cancelled' and old.status <> 'cancelled') or (new.refund_status is not null and old.refund_status is null) then
    if new.credit_used > 0 and exists (select 1 from public.credit_ledger where order_id = new.id and kind = 'spend') then
      select coalesce((value ->> 'credit_expiry_days')::int, 180) into days from public.settings where key = 'referrals';
      insert into public.credit_ledger (user_id, amount, kind, expires_at, order_id, note)
      select l.user_id, -l.amount, 'return', now() + make_interval(days => greatest(coalesce(days, 180), 1)), new.id, 'Order cancelled or refunded'
        from public.credit_ledger l where l.order_id = new.id and l.kind = 'spend'
      on conflict do nothing;
    end if;
    for r in select id from public.referral_rewards where order_id = new.id and status = 'granted' loop
      perform public.cancel_referral_reward(r.id, null, 'The order was cancelled or refunded');
    end loop;
  end if;
  return new;
end $$;

create trigger orders_credit_on_cancel after update of status, refund_status on public.orders
  for each row execute function public.orders_credit_on_cancel();

revoke execute on function public.credit_balance(uuid) from public, anon, authenticated;
revoke execute on function public.spend_credit(uuid, uuid, numeric) from public, anon, authenticated;
revoke execute on function public.grant_referral_reward(uuid, uuid, text, numeric, numeric, int, uuid, uuid) from public, anon, authenticated;
revoke execute on function public.cancel_referral_reward(uuid, uuid, text) from public, anon, authenticated;
revoke execute on function public.adjust_credit(uuid, numeric, text, uuid, int) from public, anon, authenticated;
revoke execute on function public.orders_credit_on_cancel() from public, anon, authenticated;
grant execute on function public.credit_balance(uuid) to service_role;
grant execute on function public.spend_credit(uuid, uuid, numeric) to service_role;
grant execute on function public.grant_referral_reward(uuid, uuid, text, numeric, numeric, int, uuid, uuid) to service_role;
grant execute on function public.cancel_referral_reward(uuid, uuid, text) to service_role;
grant execute on function public.adjust_credit(uuid, numeric, text, uuid, int) to service_role;

-- ---------------------------------------------------------------------------
-- 5. Finance report: platform-paid discounts (invite discounts and credit) and credit still unspent
-- ---------------------------------------------------------------------------
create or replace function public.admin_finance(p_from timestamptz, p_to timestamptz)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  result jsonb;
begin
  if not public.is_admin() then raise exception 'ADMIN_ONLY'; end if;
  with lines as (
    select oi.*
    from public.order_items oi join public.orders o on o.id = oi.order_id
    where o.paid_at >= p_from and o.paid_at < p_to and public.is_earning_status(o.status) and oi.reversed_at is null
  ), ord as (
    select * from public.orders o
    where o.paid_at >= p_from and o.paid_at < p_to and o.status <> 'pending_payment'
  )
  select jsonb_build_object(
    'book_sales_value', coalesce((select sum(unit_price * quantity) from lines), 0),
    'print_costs',      coalesce((select sum(coalesce(print_cost_total, print_cost * quantity)) from lines), 0),
    'commission',       coalesce((select sum(coalesce(commission, platform_fee * quantity)) from lines), 0),
    'commission_gst',   coalesce((select sum(coalesce(commission_gst, 0)) from lines), 0),
    'gateway_costs',    coalesce((select sum(coalesce(gateway_allocated, payment_fee * quantity)) from lines), 0),
    'author_earnings',  coalesce((select sum(public.line_earning(l::public.order_items)) from lines l), 0),
    'platform_discounts', coalesce((select sum(platform_discount) from lines), 0),
    'shipping_collected', coalesce((select sum(shipping) from ord where public.is_earning_status(status)), 0),
    'shipping_promotions', coalesce((select sum(shipping_discount) from ord where public.is_earning_status(status)), 0),
    'book_refunds',     coalesce((select sum(refund_amount) from ord where refund_status in ('processed', 'pending')), 0),
    'service_revenue',  coalesce((select sum(base_paise) from public.payments where purpose = 'service' and status in ('paid', 'partially_refunded') and paid_at >= p_from and paid_at < p_to), 0) / 100.0,
    'service_gst',      coalesce((select sum(gst_paise) from public.payments where purpose = 'service' and status in ('paid', 'partially_refunded') and paid_at >= p_from and paid_at < p_to), 0) / 100.0,
    'subscription_revenue', coalesce((select sum(base_paise) from public.payments where purpose = 'subscription' and status in ('paid', 'partially_refunded') and paid_at >= p_from and paid_at < p_to), 0) / 100.0,
    'subscription_gst', coalesce((select sum(gst_paise) from public.payments where purpose = 'subscription' and status in ('paid', 'partially_refunded') and paid_at >= p_from and paid_at < p_to), 0) / 100.0,
    'other_refunds',    coalesce((select sum(refunded_paise) from public.payments where refunded_at >= p_from and refunded_at < p_to), 0) / 100.0,
    'author_liability', coalesce((select sum(greatest(balance, 0)) from public.author_balances), 0)
  ) into result;
  return result;
end $$;

-- ===== 20261030000024_growth.sql =====
-- Growth: book reach for authors (views and sample opens), reader wishlists with price-drop and back-on-sale
-- notices, a notice to followers when an author publishes a new book, and an opt-in weekly email.
-- No personal data is stored for views: only a count per book per day.

-- ---------------------------------------------------------------------------
-- 1. Book reach: daily counts per book
-- ---------------------------------------------------------------------------
create table public.book_stats_daily (
  book_id      uuid not null references public.books (id) on delete cascade,
  day          date not null,
  views        integer not null default 0 check (views >= 0),
  sample_opens integer not null default 0 check (sample_opens >= 0),
  primary key (book_id, day)
);
alter table public.book_stats_daily enable row level security;
create policy "book stats: author and admin read" on public.book_stats_daily for select to authenticated
  using (public.is_admin() or exists (select 1 from public.books b where b.id = book_id and b.author_id = auth.uid()));

-- Counts one view or sample opening (India date). Called by the server only.
create function public.count_book_event(p_book uuid, p_kind text) returns void
language plpgsql security definer set search_path = public as $$
declare
  today date := (now() at time zone 'Asia/Kolkata')::date;
begin
  if p_kind not in ('view', 'sample') then raise exception 'Invalid event'; end if;
  insert into public.book_stats_daily (book_id, day, views, sample_opens)
  values (p_book, today, (p_kind = 'view')::int, (p_kind = 'sample')::int)
  on conflict (book_id, day) do update
     set views = book_stats_daily.views + excluded.views,
         sample_opens = book_stats_daily.sample_opens + excluded.sample_opens;
end $$;
revoke execute on function public.count_book_event(uuid, text) from public, anon, authenticated;
grant execute on function public.count_book_event(uuid, text) to service_role;

-- ---------------------------------------------------------------------------
-- 2. Wishlist ("Save for later")
-- ---------------------------------------------------------------------------
create table public.wishlist (
  user_id        uuid not null references public.profiles (id) on delete cascade,
  book_id        uuid not null references public.books (id) on delete cascade,
  price_at_save  numeric(10, 2),  -- to show "now ₹X less than when you saved it"
  created_at     timestamptz not null default now(),
  primary key (user_id, book_id)
);
create index wishlist_book_idx on public.wishlist (book_id);
alter table public.wishlist enable row level security;
create policy "wishlist: own read" on public.wishlist for select to authenticated using (user_id = auth.uid());
create policy "wishlist: own add" on public.wishlist for insert to authenticated with check (user_id = auth.uid());
create policy "wishlist: own remove" on public.wishlist for delete to authenticated using (user_id = auth.uid());

-- ---------------------------------------------------------------------------
-- 3. Preferences and the weekly email
-- ---------------------------------------------------------------------------
alter table public.profiles
  add column notify_new_books boolean not null default true,    -- an author you follow publishes a book
  add column notify_saved_books boolean not null default true,  -- a saved book gets cheaper or is back on sale
  add column weekly_digest boolean not null default false,      -- opt-in email, needs an email address
  add column digest_token uuid not null default gen_random_uuid(); -- for the one-click unsubscribe link

alter table public.email_outbox drop constraint email_outbox_kind_check;
alter table public.email_outbox add constraint email_outbox_kind_check
  check (kind in ('order_confirmed', 'order_shipped', 'order_delivered', 'order_cancelled', 'refund_processed', 'contact_message', 'weekly_digest'));

-- ---------------------------------------------------------------------------
-- 4. Book notices (in-app). ref_id makes each one unique: the book for a new book or its return to sale,
--    the book and price for a price drop (so each new lower price notifies once).
-- ---------------------------------------------------------------------------
alter table public.notifications drop constraint notifications_kind_check;
alter table public.notifications add constraint notifications_kind_check
  check (kind in ('new_article', 'new_post', 'new_follower', 'reply', 'verification', 'distribution', 'new_book', 'price_drop', 'back_on_sale'));

create function public.books_growth_notices() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  -- First time live: followers of the author (preference and blocks respected)
  if new.status = 'published' and old.status <> 'published' and old.published_at is null then
    insert into public.notifications (user_id, kind, actor_id, ref_id, title, link)
    select f.follower_id, 'new_book', new.author_id, new.id, left('New book: ' || new.title, 140), '/books/' || new.slug
      from public.follows f
      join public.profiles pr on pr.id = f.follower_id
     where f.author_id = new.author_id
       and pr.notify_new_books
       and not exists (select 1 from public.user_blocks ub
                        where (ub.blocker_id = f.follower_id and ub.blocked_id = new.author_id)
                           or (ub.blocker_id = new.author_id and ub.blocked_id = f.follower_id))
    on conflict do nothing;
  -- Live again after being taken down: readers who saved it
  elsif new.status = 'published' and old.status <> 'published' then
    insert into public.notifications (user_id, kind, actor_id, ref_id, title, link)
    select w.user_id, 'back_on_sale', new.author_id, md5(new.id::text || ':back:' || now()::date::text)::uuid,
           left('Back on sale: ' || new.title, 140), '/books/' || new.slug
      from public.wishlist w join public.profiles pr on pr.id = w.user_id
     where w.book_id = new.id and pr.notify_saved_books
    on conflict do nothing;
  end if;
  -- Cheaper while live: readers who saved it
  if new.status = 'published' and old.status = 'published' and new.mrp is not null and old.mrp is not null and new.mrp < old.mrp then
    insert into public.notifications (user_id, kind, actor_id, ref_id, title, link)
    select w.user_id, 'price_drop', new.author_id, md5(new.id::text || ':price:' || new.mrp::text)::uuid,
           left('Price drop: ' || new.title || ' is now ₹' || trim(to_char(new.mrp, 'FM999999990.##')), 140), '/books/' || new.slug
      from public.wishlist w join public.profiles pr on pr.id = w.user_id
     where w.book_id = new.id and pr.notify_saved_books
    on conflict do nothing;
  end if;
  return new;
end $$;
revoke execute on function public.books_growth_notices() from public, anon, authenticated;

create trigger books_growth_notices after update of status, mrp on public.books
  for each row execute function public.books_growth_notices();

-- ===== 20261031000025_content_checks.sql =====
-- Content checks on manuscripts.
-- Every manuscript goes through seven automatic checks before it can be sent for review (readable file, abusive
-- language, hate speech, sexual content, violence and self-harm, personal data, professional quality). The checks
-- never publish or reject by themselves: they tell the author what to fix and show our reviewers what was found.

-- ---------------------------------------------------------------------------
-- 1. The author's note to reviewers (not public)
-- ---------------------------------------------------------------------------
alter table public.books
  add column content_note text check (length(content_note) <= 1000);  -- why flagged content is there (e.g. a quote in context)

-- ---------------------------------------------------------------------------
-- 2. Check results: one row per manuscript file checked
-- ---------------------------------------------------------------------------
create table public.manuscript_checks (
  id              uuid primary key default gen_random_uuid(),
  book_id         uuid not null references public.books (id) on delete cascade,
  manuscript_path text not null,
  status          text not null check (status in ('done', 'error')),
  overall         text not null check (overall in ('pass', 'review', 'blocked')),
  results         jsonb not null default '[]',   -- the seven checks: key, status, count, detail, examples (page + masked text)
  pages           integer,
  words           integer,
  error           text check (length(error) <= 500),
  created_at      timestamptz not null default now(),
  unique (book_id, manuscript_path)
);
create index manuscript_checks_book_idx on public.manuscript_checks (book_id, created_at desc);
alter table public.manuscript_checks enable row level security;
create policy "manuscript checks: author and admin read" on public.manuscript_checks for select to authenticated
  using (public.is_admin() or exists (select 1 from public.books b where b.id = book_id and b.author_id = auth.uid()));

-- ---------------------------------------------------------------------------
-- 3. Words and phrases our team adds to the built-in lists (or allows, to stop false alarms)
-- ---------------------------------------------------------------------------
create table public.content_terms (
  term       text not null check (length(term) between 2 and 80),
  category   text not null check (category in ('language', 'hate', 'adult', 'violence', 'allow')),
  created_by uuid references public.profiles (id) on delete set null,
  created_at timestamptz not null default now(),
  primary key (term, category)
);
alter table public.content_terms enable row level security;
create policy "content terms: admin" on public.content_terms for all using (public.is_admin()) with check (public.is_admin());
